window.CFA_DATA={"meta": {"title": "CFA PASS SYSTEM", "level": "Level I", "curriculumYear": 2027, "status": "Verified curriculum map; original study content is being expanded", "officialOutline": "2027 Level I Topic Outlines", "examFormat": "180 multiple-choice questions; two 135-minute sessions; three choices per question", "edition": "V8 Economics and Corporate Finance", "questionCount": 474, "accuracyNote": "Official structure is verified; guides and questions are original and independently written.", "features": ["Search", "Confidence tracking", "Adaptive review", "Timed sessions", "Why each answer is correct", "Offline progress backup"], "completedFsaModules": 7, "completedDetailedLessons": 14}, "topics": [{"id": "quant", "name": "Quantitative Methods", "weight": "6–9%", "modules": [{"title": "Returns of Financial Assets and Instruments", "los": ["describe, compare, and interpret returns", "describe, compare, and interpret required rates of return, risk-free rates, risk premia, and inflation"]}, {"title": "Types of Financial Returns", "los": ["calculate, compare, and interpret different types of returns for financial assets, instruments, and indicators"]}, {"title": "Benchmarking Returns", "los": ["calculate and compare money-weighted and time-weighted rates of return", "describe the choices and the implications of the different weighting methods used in index construction and management, and calculate, interpret, and explain the value and the returns of an index"]}, {"title": "The Time Value of Money in Finance", "los": ["calculate and interpret the present value of fixed-income and equity instruments based on expected future cash flows Quantitative Methods", "calculate and interpret the implied return of fixed-income instruments and required return and implied growth of equity instruments given their present value and cash flows", "explain the cash flow additivity principle and its importance for the condition of no arbitrage, and explain its use in calculating implied forward interest rates, forward exchange rates, and option values"]}, {"title": "Statistical Characteristics of Asset Returns", "los": ["calculate, interpret, and evaluate various measures of (1) central tendency and location and (2) dispersion", "describe, interpret, and evaluate measures of skewness and kurtosis", "calculate, interpret, and evaluate covariance and correlation", "calculate, interpret, and evaluate semi-deviation and coefficient of variation"]}, {"title": "Statistical Distributions for Financial Asset Prices and Returns", "los": ["calculate, interpret, and evaluate unconditional expected values for mean, variance, and covariance", "calculate, interpret, and evaluate the principal moments of key statistical distributions used in finance", "calculate, interpret, and evaluate conditional expectations, variances, and covariances", "formulate investment problems through Bayesian updating"]}, {"title": "Estimation and Hypothesis Testing", "los": ["explain the central limit theorem and the application of confidence intervals and sampling methodologies", "explain hypothesis testing and its components, including statistical significance, Type I and Type II errors, and the power of a test; construct appropriate hypothesis tests; and interpret the results", "compare and contrast parametric and non-parametric tests, describe situations in which each is the more appropriate type of test, construct appropriate hypothesis tests, and interpret the results"]}, {"title": "The Return and Risk of a Financial Portfolio", "los": ["calculate, interpret, and evaluate the expected return, variance, standard deviation, covariance, and correlation of portfolio returns", "describe, calculate, and interpret the minimum-variance portfolio and portfolios that lie on the efficient frontier", "explain the selection of an optimal portfolio, given an investor’s risk aversion and the capital allocation line, and how this extends to the market portfolio and the capital market line"]}, {"title": "Simulation of Financial Asset Prices and Returns", "los": ["describe historical simulation and explain how it can be used in investment applications Quantitative Methods 3", "describe bootstrap resampling, and explain how it can be used in investment applications", "describe Monte Carlo simulation and explain how it can be used in investment applications"]}, {"title": "Applications of Simple Linear Regression in Finance", "los": ["describe, interpret, and explain simple linear regression, including coefficient estimation using the least squares criterion", "describe and compare the assumptions of simple linear regression, identify violations through analyzing residuals, evaluate the estimated model’s goodness-of-fit and regression coefficients, and results of ANOVA estimates", "calculate and interpret predicted values, the standard error of the estimate, and prediction intervals for the dependent variable in a simple linear regression model and describe different functional forms", "calculate and interpret the variable estimates of the capital asset pricing model (CAPM)"]}, {"title": "Introduction to Financial Data Science", "los": ["describe how big data, machine learning, and artificial intelligence are used in financial data science, fintech, and investment management Level I Topic Outlines"]}]}, {"id": "economics", "name": "Economics", "weight": "6–9%", "modules": [{"title": "The Firm and Market Structures", "los": ["determine and interpret breakeven and shutdown points of production, as well as how economies and diseconomies of scale affect costs under perfect and imperfect competition", "describe characteristics of perfect competition, monopolistic competition, oligopoly, and pure monopoly", "explain supply and demand relationships under monopolistic competition, including the optimal price and output for firms as well as pricing strategy", "explain supply and demand relationships under oligopoly, including the optimal price and output for firms as well as pricing strategy", "identify the type of market structure within which a firm operates and describe the use and limitations of concentration measures"]}, {"title": "Understanding Business Cycles", "los": ["describe the business cycle and its phases", "describe credit cycles", "describe how resource use, consumer and business activity, housing sector activity, and external trade sector activity vary over the business cycle and describe their measurement using economic indicators Economics"]}, {"title": "Fiscal Policy", "los": ["compare monetary and fiscal policy", "describe roles and objectives of fiscal policy as well as arguments as to whether the size of a national debt relative to GDP matters", "describe tools of fiscal policy, including their advantages and disadvantages", "explain the implementation of fiscal policy and difficulties of implementation as well as whether a fiscal policy is expansionary or contractionary"]}, {"title": "Monetary Policy", "los": ["describe the roles and objectives of central banks", "describe tools used to implement monetary policy tools and the monetary transmission mechanism, and explain the relationships between monetary policy and economic growth, inflation, interest, and exchange rates", "describe qualities of effective central banks; contrast their use of inflation, interest rate, and exchange rate targeting in expansionary or contractionary monetary policy; and describe the limitations of monetary policy", "explain the interaction of monetary and fiscal policy"]}, {"title": "Introduction to Geopolitics", "los": ["describe geopolitics from a cooperation versus competition perspective", "describe geopolitics and its relationship with globalization", "describe functions and objectives of the international organizations that facilitate trade, including the World Bank, the International Monetary Fund, and the World Trade Organization", "describe geopolitical risk", "describe tools of geopolitics and their impact on regions and economies", "describe the impact of geopolitical risk on investments"]}, {"title": "International Trade", "los": ["describe the benefits and costs of international trade", "compare types of trade restrictions, such as tariffs, quotas, and export subsidies, and their economic implications", "explain motivations for and advantages of trading blocs, common markets, and economic unions"]}, {"title": "Capital Flows and the FX Market", "los": ["describe the foreign exchange market, including its functions and participants, distinguish between nominal and real exchange rates, and calculate and interpret the percentage change in a currency relative to another currency", "describe exchange rate regimes and explain the effects of exchange rates on countries’ international trade and capital flows", "describe common objectives of capital restrictions imposed by governments Economics 7"]}, {"title": "Exchange Rate Calculations", "los": ["calculate and interpret currency cross-rates", "explain the arbitrage relationship between spot and forward exchange rates and interest rates, calculate a forward rate using points or in percentage terms, and interpret a forward discount or premium"]}]}, {"id": "corporate", "name": "Corporate Finance", "weight": "6–9%", "modules": [{"title": "Organizational Forms, Corporate Issuer Features, and Ownership", "los": ["compare the organizational forms of businesses", "describe key features of corporate issuers", "compare publicly and privately owned corporate issuers"]}, {"title": "Investors and Other Stakeholders", "los": ["compare the financial claims and motivations of lenders and shareholders", "describe a company’s stakeholder groups and compare their interests", "describe environmental, social, and governance factors of corporate issuers considered by investors"]}, {"title": "Corporate Governance: Conflicts, Mechanisms, Risks, and Benefits", "los": ["describe the principal-agent relationship and conflicts that may arise between stakeholder groups", "describe corporate governance and mechanisms to manage stakeholder relationships and mitigate associated risks", "describe potential risks of poor corporate governance and stakeholder management and benefits of effective corporate governance and stakeholder management Corporate Finance"]}, {"title": "Working Capital and Liquidity", "los": ["explain the cash conversion cycle and compare issuers’ cash conversion cycles", "explain liquidity and compare issuers’ liquidity levels", "describe issuers’ objectives and compare methods for managing working capital and liquidity"]}, {"title": "Capital Investments and Capital Allocation", "los": ["describe types of capital investments", "describe the capital allocation process, calculate net present value (NPV), internal rate of return (IRR), and return on invested capital (ROIC), and contrast their use in capital allocation", "describe principles of capital allocation and common capital allocation pitfalls", "describe types of real options relevant to capital investments"]}, {"title": "Capital Structure", "los": ["calculate and interpret the weighted-average cost of capital for a company", "explain factors affecting capital structure and the weighted-average cost of capital", "explain the Modigliani–Miller propositions regarding capital structure", "describe optimal and target capital structures"]}, {"title": "Business Models", "los": ["describe key features of business models", "describe various types of business models"]}]}, {"id": "fsa", "name": "Financial Statement Analysis", "weight": "11–14%", "modules": [{"title": "Introduction to Financial Statement Analysis", "los": ["describe the steps in the financial statement analysis framework", "describe the roles of financial statement analysis", "describe the importance of regulatory filings, financial statement notes and supplementary information, management’s commentary, and audit reports", "describe implications for financial analysis of alternative financial reporting systems and the importance of monitoring developments in financial reporting standards", "describe information sources that analysts use in financial statement analysis besides annual and interim financial reports"]}, {"title": "Analyzing Income Statements", "los": ["describe general principles of revenue recognition, specific revenue recognition applications, and implications of revenue recognition choices for financial analysis", "describe general principles of expense recognition, specific expense recognition applications, implications of expense recognition choices for financial analysis and contrast costs that are capitalized versus those that are expensed in the period in which they are incurred", "describe the financial reporting treatment and analysis of non-recurring items (including discontinued operations, unusual or infrequent items) and changes in accounting policies Financial Statement Analysis", "describe how earnings per share is calculated and calculate and interpret a company’s basic and diluted earnings per share for companies with simple and complex capital structures including those with antidilutive securities", "evaluate a company’s financial performance using common-size income statements and financial ratios based on the income statement"]}, {"title": "Analyzing Balance Sheets", "los": ["explain the financial reporting and disclosures related to intangible assets", "explain the financial reporting and disclosures related to goodwill", "explain the financial reporting and disclosures related to financial instruments", "explain the financial reporting and disclosures related to non-current liabilities", "calculate and interpret common-size balance sheets and related financial ratios"]}, {"title": "Analyzing Statements of Cash Flows I", "los": ["describe how the cash flow statement is linked to the income statement and the balance sheet", "describe the steps in the preparation of direct and indirect cash flow statements, including how cash flows can be computed using income statement and balance sheet data", "demonstrate the conversion of cash flows from the indirect to direct method", "contrast cash flow statements prepared under International Financial Reporting Standards (IFRS) and US generally accepted accounting principles (US GAAP)"]}, {"title": "Analyzing Statements of Cash Flows II", "los": ["analyze and interpret both reported and common-size cash flow statements", "calculate and interpret free cash flow to the firm, free cash flow to equity, and performance and coverage cash flow ratios"]}, {"title": "Analysis of Inventories", "los": ["describe the measurement of inventory at the lower of cost and net realisable value and its implications for financial statements and ratios", "calculate and explain how inflation and deflation of inventory costs affect the financial statements and ratios of companies that use different inventory valuation methods", "describe the presentation and disclosures relating to inventories and explain issues that analysts should consider when examining a company’s inventory disclosures and other sources of information"]}, {"title": "Analysis of Long-Term Assets", "los": ["compare the financial reporting of the following types of intangible assets: purchased, internally developed, and acquired in a business combination", "explain and evaluate how impairment and derecognition of property, plant, and equipment and intangible assets affect the financial statements and ratios", "analyze and interpret financial statement disclosures regarding property, plant, and equipment and intangible assets Financial Statement Analysis 13"]}, {"title": "Topics in Long-Term Liabilities and Equity", "los": ["explain the financial reporting of leases from the perspectives of lessors and lessees", "explain the financial reporting of defined contribution, defined benefit, and stock-based compensation plans", "describe the financial statement presentation of and disclosures relating to long-term liabilities and share-based compensation"]}, {"title": "Analysis of Income Taxes", "los": ["contrast accounting profit, taxable income, taxes payable, and income tax expense and temporary versus permanent differences between accounting profit and taxable income", "explain how deferred tax liabilities and assets are created and the factors that determine how a company’s deferred tax liabilities and assets should be treated for the purposes of financial analysis", "calculate, interpret, and contrast an issuer’s effective tax rate, statutory tax rate, and cash tax rate", "analyze disclosures relating to deferred tax items and the effective tax rate reconciliation and explain how information included in these disclosures affects a company’s financial statements and financial ratios"]}, {"title": "Financial Reporting Quality", "los": ["compare financial reporting quality with the quality of reported results (including quality of earnings, cash flow, and balance sheet items)", "describe a spectrum for assessing financial reporting quality", "explain the difference between conservative and aggressive accounting", "describe motivations that might cause management to issue financial reports that are not high quality and conditions that are conducive to issuing low-quality, or even fraudulent, financial reports", "describe mechanisms that discipline financial reporting quality and the potential limitations of those mechanisms", "describe presentation choices, including non-GAAP measures, that could be used to influence an analyst’s opinion", "describe accounting methods (choices and estimates) that could be used to manage earnings, cash flow, and balance sheet items", "describe accounting warning signs and methods for detecting manipulation of information in financial reports"]}, {"title": "Financial Analysis Techniques", "los": ["describe tools and techniques used in financial analysis, including their uses and limitations", "calculate and interpret activity, liquidity, solvency, and profitability ratios", "describe relationships among ratios and evaluate a company using ratio analysis", "demonstrate the application of DuPont analysis of return on equity and calculate and interpret effects of changes in its components", "describe the uses of industry-specific ratios used in financial analysis", "describe how ratio analysis and other techniques can be used to model and forecast earnings Financial Statement Analysis"]}, {"title": "Introduction to Financial Statement Modeling", "los": ["demonstrate the development of a sales-based pro forma company model", "explain how behavioral factors affect analyst forecasts and recommend remedial actions for analyst biases", "explain how the competitive position of a company based on a Porter’s five forces analysis affects prices and costs", "explain how to forecast industry and company sales and costs when they are subject to price inflation or deflation"]}]}, {"id": "equity", "name": "Equities", "weight": "11–14%", "modules": [{"title": "Equity Instrument Features", "los": ["describe basic features and types of equity instruments", "contrast features of publicly listed versus private equity securities"]}, {"title": "Equity Jurisdictions, Classes, and the Voting Process", "los": ["describe differences in economic and voting rights and other characteristics among different jurisdictions and equity classes", "describe the voting process and roles of the issuer’s management, board, proxy advisors, asset managers, and asset owners in the process"]}, {"title": "Equity Issuance and Trading", "los": ["describe primary and secondary public equity markets and their functions", "compare exchange, off-exchange, and over-the-counter equities trading", "describe liquidity measures for a publicly listed security and calculate float and average daily volume", "describe types of equity indexes Equities"]}, {"title": "Sources of Equity Returns", "los": ["describe features and uses of dividends, share repurchases, stock splits, and reverse stock splits", "describe dividend payment chronology", "calculate price and total return for equity securities"]}, {"title": "Introduction to Equity Valuation", "los": ["contrast price and value for an equity security", "contrast the use of book value of equity, market capitalization, and enterprise value as indicators of intrinsic value", "describe major categories of equity valuation models and explain their advantages and disadvantages"]}, {"title": "Discounted Cash Flow (DCF) and Growth Models", "los": ["contrast the inputs used in dividend discount, free cash flow to equity (FCFE), free cash flow to the firm (FCFF), and residual income models, and explain the process for using present value models to value equity", "calculate and interpret the intrinsic value of an equity security based on present value models that assume constant cash flow growth or multistage cash flow growth", "explain the shortcomings of constant and multistage cash flow growth assumptions in present value models", "calculate the intrinsic value of a non-callable, non-convertible preferred stock and describe how contingency features affect intrinsic value"]}, {"title": "Relative Value Equity Valuation Approaches", "los": ["explain the process for using multiples to value equity based on the method of comparables and the method of forecasted fundamentals", "calculate and interpret price and enterprise value multiples, and describe their appropriate uses", "determine a potential peer group for multiples-based equity valuation based on a company’s industry classification or specific drivers of expected return", "describe the use of multiples based on past, current, and projected future values in estimating equity value"]}, {"title": "Financial Statement Forecasting in Equity Valuation", "los": ["explain the rationale, construction, and uses of financial statement forecast models in equity valuation", "evaluate the construction of an equity valuation model based on characteristics of the subject company", "estimate and interpret the value of an equity security based on the outputs of a financial statement forecast model Equities 17"]}, {"title": "Industry and Competitive Analysis", "los": ["describe the process of industry and competitive analysis", "describe industry classification methods and compare methods by which companies can be grouped", "determine an industry’s size, growth characteristics, profitability, and market share trends", "analyze an industry’s structure and external influences using Porter’s Five Forces and the PESTLE framework"]}, {"title": "Company Analysis: Past, Present, and Future", "los": ["explain a company’s competitive strategy and position within an industry", "evaluate a company’s revenue drivers, operating profitability, and pricing power", "evaluate a company’s working capital, capital investments, and capital structure"]}, {"title": "Equity Analyst Research Reports", "los": ["describe the elements that should be covered in a detailed company research report", "compare sell-side and buy-side equity analyst reports and their conclusions", "explain why value estimates from the same modeling approach may differ based on analyst assumptions regarding revenue, profitability, investment, and financing The Capital Asset Pricing Model, Market Model, and Other Factor-Based Equity Models"]}]}, {"id": "fixed", "name": "Fixed Income", "weight": "11–14%", "modules": [{"title": "Fixed-Income Instrument Features", "los": ["describe the features of a fixed-income security", "describe the contents of a bond indenture and contrast affirmative and negative covenants"]}, {"title": "Fixed-Income Cash Flows and Types", "los": ["describe common cash flow structures of fixed-income instruments and contrast cash flow contingency provisions that benefit issuers and investors", "describe how legal, regulatory, and tax considerations affect the issuance and trading of fixed-income securities"]}, {"title": "Fixed-Income Issuance and Trading", "los": ["describe fixed-income market segments and their issuer and investor participants", "describe types of fixed-income indexes", "compare primary and secondary fixed-income markets to equity markets Fixed Income"]}, {"title": "Fixed-Income Markets for Corporate Issuers", "los": ["compare short-term funding alternatives available to corporations and financial institutions", "describe repurchase agreements (repos), their uses, and their benefits and risks", "contrast the long-term funding of investment-grade versus high-yield corporate issuers"]}, {"title": "Fixed-Income Markets for Government Issuers", "los": ["describe funding choices by sovereign and non-sovereign governments, quasi-government entities, and supranational agencies", "contrast the issuance and trading of government and corporate fixed-income instruments"]}, {"title": "Fixed-Income Bond Valuation: Prices and Yields", "los": ["calculate a bond’s price given a yield-to-maturity on or between coupon dates", "identify the relationships among a bond’s price, coupon rate, maturity, and yield-to-maturity", "describe matrix pricing"]}, {"title": "Yield and Yield Spread Measures for Fixed-Rate Bonds", "los": ["calculate annual yield on a bond for varying compounding periods in a year", "compare, calculate, and interpret yield and yield spread measures for fixed-rate bonds"]}, {"title": "Yield and Yield Spread Measures for Floating-Rate Instruments", "los": ["calculate and interpret yield spread measures for floating-rate instruments", "calculate and interpret yield measures for money market instruments"]}, {"title": "The Term Structure of Interest Rates: Spot, Par, and Forward Curves", "los": ["define spot rates and the spot curve, and calculate the price of a bond using spot rates", "define par and forward rates, and calculate par rates, forward rates from spot rates, spot rates from forward rates, and the price of a bond using forward rates", "compare the spot curve, par curve, and forward curve"]}, {"title": "Interest Rate Risk and Return", "los": ["calculate and interpret the sources of return from investing in a fixed-rate bond", "describe the relationships among a bond’s holding period return, its Macaulay duration, and the investment horizon", "define, calculate, and interpret Macaulay duration. Fixed Income 21"]}, {"title": "Yield-Based Bond Duration Measures and Properties", "los": ["define, calculate, and interpret modified duration, money duration, and the price value of a basis point (PVBP)", "explain how a bond’s maturity, coupon, and yield level affect its interest rate risk"]}, {"title": "Yield-Based Bond Convexity and Portfolio Properties", "los": ["calculate and interpret convexity and describe the convexity adjustment", "calculate the percentage price change of a bond for a specified change in yield, given the bond’s duration and convexity", "calculate portfolio duration and convexity and explain the limitations of these measures"]}, {"title": "Curve-Based and Empirical Fixed-Income Risk Measures", "los": ["explain why effective duration and effective convexity are the most appropriate measures of interest rate risk for bonds with embedded options", "calculate the percentage price change of a bond for a specified change in benchmark yield, given the bond’s effective duration and convexity", "define key rate duration and describe its use to measure price sensitivity of fixed-income instruments to benchmark yield curve changes", "describe the difference between empirical duration and analytical duration"]}, {"title": "Credit Risk", "los": ["describe credit risk and its components, probability of default and loss given default", "describe the uses of ratings from credit rating agencies and their limitations", "describe macroeconomic, market, and issuer-specific factors that influence the level and volatility of yield spreads"]}, {"title": "Credit Analysis for Government Issuers", "los": ["explain special considerations when evaluating the credit of sovereign and non-sovereign government debt issuers and issues"]}, {"title": "Credit Analysis for Corporate Issuers", "los": ["describe the qualitative and quantitative factors used to evaluate a corporate borrower’s creditworthiness", "calculate and interpret financial ratios used in credit analysis", "describe the seniority rankings of debt, secured versus unsecured debt and the priority of claims in bankruptcy, and their impact on credit ratings"]}, {"title": "Fixed-Income Securitization", "los": ["explain benefits of securitization for issuers, investors, economies, and financial markets", "describe securitization, including the parties and the roles they play Fixed Income"]}, {"title": "Asset-Backed Security (ABS) Instrument and Market Features", "los": ["describe characteristics and risks of covered bonds and how they differ from other asset-backed securities", "describe typical credit enhancement structures used in securitizations", "describe types and characteristics of non-mortgage asset-backed securities, including the cash flows and risks of each type"]}]}, {"id": "derivatives", "name": "Derivatives", "weight": "5–8%", "modules": [{"title": "Mortgage-Backed Security (MBS) Instrument and Market Features", "los": ["define prepayment risk and describe time tranching structures in securitizations and their purpose", "describe fundamental features of residential mortgage loans that are securitized", "describe types and characteristics of residential mortgage-backed securities, including mortgage pass-through securities and collateralized mortgage obligations, and explain the cash flows and risks for each type", "describe characteristics and risks of commercial mortgage-backed securities Level I Topic Outlines Derivatives LEARNING OUTCOMES"]}, {"title": "Derivative Instrument and Derivative Market Features", "los": ["define a derivative and describe basic features of a derivative instrument", "describe the basic features of derivative markets, and contrast over-the-counter and exchange-traded derivative markets"]}, {"title": "Forward Commitment and Contingent Claim Features and Instruments", "los": ["define forward contracts, futures contracts, swaps, options (calls and puts), and credit derivatives and compare their basic characteristics", "determine the value at expiration and profit from a long or a short position in a call or put option", "contrast forward commitments with contingent claims"]}, {"title": "Derivative Benefits, Risks, and Issuer and Investor Uses", "los": ["describe benefits and risks of derivative instruments", "compare the use of derivatives among issuers and investors"]}, {"title": "Arbitrage, Replication, and the Cost of Carry in Pricing Derivatives", "los": ["explain how the concepts of arbitrage and replication are used in pricing derivatives Derivatives", "explain the difference between the spot and expected future price of an underlying and the cost of carry associated with holding the underlying asset Pricing and Valuation of Forward Contracts and for an Underlying with Varying"]}, {"title": "Pricing and Valuation of Forward Contracts and for an Underlying with Varying Maturities", "los": ["explain how the value and price of a forward contract are determined at initiation, during the life of the contract, and at expiration", "explain how forward rates are determined for interest rate forward contracts and describe the uses of these forward rates."]}, {"title": "Pricing and Valuation of Futures Contracts", "los": ["compare the value and price of forward and futures contracts", "explain why forward and futures prices differ"]}, {"title": "Pricing and Valuation of Interest Rate and Other Swaps", "los": ["describe how swap contracts are similar to but different from a series of forward contracts", "contrast the value and price of swaps"]}, {"title": "Pricing and Valuation of Options", "los": ["explain the exercise value, moneyness, and time value of an option", "contrast the use of arbitrage and replication concepts in pricing forward"]}]}, {"id": "alternatives", "name": "Alternative Investments", "weight": "7–10%", "modules": [{"title": "Option Replication Using Put–Call Parity", "los": ["explain put–call parity for European options", "explain put–call forward parity for European options"]}, {"title": "Valuing a Derivative Using a One-Period Binomial Model", "los": ["explain how to value a derivative using a one-period binomial model", "describe the concept of risk neutrality in derivatives pricing Level I Topic Outlines Alternative Investments LEARNING OUTCOMES"]}, {"title": "Alternative Investment Features, Methods, and Structures", "los": ["describe features and categories of alternative investments", "compare direct investment, co-investment, and fund investment methods for alternative investments", "describe investment ownership and compensation structures commonly used in alternative investments"]}, {"title": "Alternative Investment Performance and Returns", "los": ["describe the performance appraisal of alternative investments", "calculate and interpret alternative investment returns both before and after fees"]}, {"title": "Investments in Private Capital: Equity and Debt", "los": ["explain features of private equity and its investment characteristics", "explain features of private debt and its investment characteristics", "describe the diversification benefits that private capital can provide"]}, {"title": "Real Estate and Infrastructure", "los": ["explain features and characteristics of real estate", "explain the investment characteristics of real estate investments Alternative Investments", "explain features and characteristics of infrastructure", "explain the investment characteristics of infrastructure investments"]}, {"title": "Natural Resources", "los": ["explain features of raw land, timberland, and farmland and their investment characteristics", "describe features of commodities and their investment characteristics", "analyze sources of risk, return, and diversification among natural resource investments Hedge Funds"]}]}, {"id": "portfolio", "name": "Portfolio Construction", "weight": "8–12%", "modules": [{"title": "Introduction to Digital Assets", "los": ["describe financial applications of distributed ledger technology", "explain investment features of digital assets and contrast them with other asset classes", "describe investment forms and vehicles used in digital asset investments", "analyze sources of risk, return, and diversification among digital asset investments Level I Topic Outlines Portfolio Construction LEARNING OUTCOMES"]}, {"title": "Portfolio Risk and Return: Part I", "los": ["describe characteristics of the major asset classes that investors consider in forming portfolios", "explain risk aversion and its implications for portfolio selection", "explain the selection of an optimal portfolio, given an investor’s utility (or risk aversion) and the capital allocation line", "calculate and interpret the mean, variance, and covariance (or correlation) of asset returns based on historical data", "calculate and interpret portfolio standard deviation", "describe the effect on a portfolio’s risk of investing in assets that are less than perfectly correlated", "describe and interpret the minimum-variance and efficient frontiers of risky assets and the global minimum-variance portfolio"]}, {"title": "Portfolio Risk and Return: Part II", "los": ["describe the implications of combining a risk-free asset with a portfolio of risky assets", "explain the capital allocation line (CAL) and the capital market line (CML)", "explain systematic and nonsystematic risk, including why an investor should not expect to receive additional return for bearing nonsystematic risk", "explain return generating models (including the market model) and their uses", "calculate and interpret beta Portfolio Construction", "explain the capital asset pricing model (CAPM), including its assumptions, and the security market line (SML)", "calculate and interpret the expected return of an asset using the CAPM", "describe and demonstrate applications of the CAPM and the SML", "calculate and interpret the Sharpe ratio, Treynor ratio, M2, and Jensen’s alpha"]}, {"title": "Portfolio Management: An Overview", "los": ["describe the portfolio approach to investing", "describe the steps in the portfolio management process", "describe types of investors and distinctive characteristics and needs of each", "describe defined contribution and defined benefit pension plans", "describe aspects of the asset management industry", "describe mutual funds and compare them with other pooled investment products"]}, {"title": "Basics of Portfolio Planning and Construction", "los": ["describe the reasons for a written investment policy statement (IPS)", "describe the major components of an IPS", "describe risk and return objectives and how they may be developed for a client", "explain the difference between the willingness and the ability (capacity) to take risk in analyzing an investor’s financial risk tolerance", "describe the investment constraints of liquidity, time horizon, tax concerns, legal and regulatory factors, and unique circumstances and their implications for the choice of portfolio assets", "explain the specification of asset classes in relation to asset allocation", "describe the principles of portfolio construction and the role of asset allocation in relation to the IPS", "describe how environmental, social, and governance (ESG) considerations may be integrated into portfolio planning and construction"]}]}, {"id": "ethics", "name": "Ethical and Professional Standards", "weight": "15–20%", "modules": [{"title": "Introduction to Risk Management", "los": ["define risk management", "describe features of a risk management framework", "define risk governance and describe elements of effective risk governance", "explain how risk tolerance affects risk management", "describe risk budgeting and its role in risk governance", "identify financial and non-financial sources of risk and describe how they may interact", "describe methods for measuring and modifying risk exposures and factors to consider in choosing among the methods Level I Topic Outlines Ethical and Professional Standards LEARNING OUTCOMES"]}, {"title": "Ethics and Trust in the Investment Profession", "los": ["explain ethics", "describe the role of a code of ethics in defining a profession", "describe professions and how they establish trust", "describe the need for high ethical standards in investment management", "explain professionalism in investment management", "identify challenges to ethical behavior", "compare and contrast ethical standards with legal standards", "describe a framework for ethical decision-making"]}, {"title": "Code of Ethics and Standards of Professional Conduct", "los": ["describe the structure of the CFA Institute Professional Conduct Program and the process for the enforcement of the Code and Standards", "identify the six components of the Code of Ethics and the seven Standards of Professional Conduct", "explain the ethical responsibilities required by the Code and Standards, including the sub-sections of each Standard Ethical and Professional Standards"]}, {"title": "Guidance for Standard I: Professionalism", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards"]}, {"title": "Guidance for Standard II: Integrity of Capital Markets", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards"]}, {"title": "Guidance for Standard III: Duties to Clients", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards"]}, {"title": "Guidance for Standard IV: Duties to Employers", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards"]}, {"title": "Guidance for Standard V: Investment Analysis, Recommendations, and Actions", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards"]}, {"title": "Guidance for Standard VI: Conflicts of Interest", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity Ethical and Professional Standards 31", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards Guidance for Standard VII: Responsibilities as a"]}, {"title": "Guidance for Standard VII: Responsibilities as a CFA Institute Member or CFA Candidate", "los": ["demonstrate a thorough knowledge of the CFA Institute Code of Ethics and Standards of Professional Conduct by interpreting the Code and Standards in various situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code and Standards"]}, {"title": "Application of the Code and Standards: Level I", "los": ["evaluate practices, policies, and conduct relative to the CFA Institute Code of Ethics and Standards of Professional Conduct", "explain how the practices, policies, and conduct do or do not violate the CFA Institute Code of Ethics and Standards of Professional Conduct"]}]}], "questions": [{"topic": "quant", "q": "A portfolio earns 20% in year 1 and loses 20% in year 2. Its two-year geometric mean annual return is closest to:", "choices": ["−2.0%", "0.0%", "2.0%"], "a": 0, "why": "Ending wealth is 1.20×0.80=0.96. √0.96−1≈−2.02%."}, {"topic": "quant", "q": "The present value of 121 received in two years at 10% annually is:", "choices": ["100", "110", "121"], "a": 0, "why": "121/(1.10)^2 = 100."}, {"topic": "quant", "q": "Compared with the arithmetic mean, the geometric mean of a variable return series is generally:", "choices": ["greater", "equal or lower", "always negative"], "a": 1, "why": "Volatility drag makes the geometric mean no greater than the arithmetic mean."}, {"topic": "quant", "q": "A larger sample size, all else equal, most likely causes the standard error of the sample mean to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 1, "why": "Standard error is s/√n."}, {"topic": "quant", "q": "A p-value is best described as the probability, assuming the null is true, of observing:", "choices": ["the null hypothesis", "a result at least as extreme as the sample result", "a Type II error"], "a": 1, "why": "The p-value measures how unusual the result is under the null."}, {"topic": "quant", "q": "Failure to reject a null hypothesis means the analyst should conclude that the null is:", "choices": ["proven true", "not rejected with the available evidence", "false"], "a": 1, "why": "Failure to reject is not proof of truth."}, {"topic": "quant", "q": "A correlation coefficient of −1 indicates:", "choices": ["no relationship", "a perfect negative linear relationship", "a nonlinear positive relationship"], "a": 1, "why": "−1 is perfect negative linear association."}, {"topic": "quant", "q": "Which return measure is most affected by the timing and size of external cash flows?", "choices": ["Time-weighted return", "Money-weighted return", "Geometric mean return"], "a": 1, "why": "Money-weighted return is an IRR and reflects cash-flow timing."}, {"topic": "quant", "q": "In simple linear regression, the slope coefficient measures the expected change in:", "choices": ["X for a one-unit change in Y", "Y for a one-unit change in X", "the error term for a one-unit change in X"], "a": 1, "why": "The slope is the change in dependent variable Y per unit of X."}, {"topic": "quant", "q": "Monte Carlo simulation differs from historical simulation because Monte Carlo most directly uses:", "choices": ["only actual historical observations", "random draws from an assumed model", "no probability distribution"], "a": 1, "why": "Monte Carlo generates random scenarios from a specified model or distribution."}, {"topic": "economics", "q": "An increase in consumer income for a normal good most likely shifts:", "choices": ["demand left", "demand right", "supply right"], "a": 1, "why": "Demand for a normal good rises with income."}, {"topic": "economics", "q": "If demand is price inelastic, a price increase will most likely cause total revenue to:", "choices": ["increase", "decrease", "remain exactly unchanged"], "a": 0, "why": "Quantity falls proportionally less than price rises."}, {"topic": "economics", "q": "A binding minimum wage is an example of a:", "choices": ["price ceiling", "price floor", "quantity subsidy"], "a": 1, "why": "It sets a minimum price for labor."}, {"topic": "economics", "q": "In perfect competition, an individual firm is best described as a:", "choices": ["price maker", "price taker", "monopolist"], "a": 1, "why": "Many sellers and homogeneous products leave firms without pricing power."}, {"topic": "economics", "q": "Real GDP differs from nominal GDP because real GDP adjusts for changes in:", "choices": ["population only", "the price level", "net exports only"], "a": 1, "why": "Real GDP measures output using constant prices."}, {"topic": "economics", "q": "Expansionary monetary policy most directly aims initially to:", "choices": ["reduce liquidity", "lower short-term interest rates or ease financial conditions", "raise taxes"], "a": 1, "why": "Central banks typically add liquidity or reduce policy rates."}, {"topic": "economics", "q": "A currency quoted as SEK/USD = 10.50 means:", "choices": ["one SEK costs USD 10.50", "one USD costs SEK 10.50", "ten USD cost SEK 0.50"], "a": 1, "why": "The quote is units of SEK per USD."}, {"topic": "economics", "q": "A country running a current-account deficit must, in accounting terms, have an offsetting:", "choices": ["capital and financial account surplus", "government budget surplus", "trade surplus"], "a": 0, "why": "Balance-of-payments accounts must offset, subject to statistical discrepancy."}, {"topic": "economics", "q": "A leading economic indicator is intended to:", "choices": ["change after the economy", "turn before broad economic activity", "measure only inflation"], "a": 1, "why": "Leading indicators tend to turn ahead of the overall cycle."}, {"topic": "economics", "q": "An increase in expected inflation, all else equal, most likely causes nominal interest rates to:", "choices": ["fall", "rise", "remain fixed by definition"], "a": 1, "why": "The Fisher relation links nominal rates to real rates and expected inflation."}, {"topic": "corporate", "q": "A sunk cost in capital budgeting should generally be:", "choices": ["included as an outflow", "excluded", "discounted at the risk-free rate"], "a": 1, "why": "It has already occurred and is not incremental."}, {"topic": "corporate", "q": "An opportunity cost is best described as:", "choices": ["a past expenditure", "the value of the best alternative forgone", "a noncash accounting charge"], "a": 1, "why": "Using a resource sacrifices its best alternative use."}, {"topic": "corporate", "q": "For mutually exclusive projects with conflicting rankings, the preferred value-maximizing criterion is usually:", "choices": ["payback", "NPV", "accounting return"], "a": 1, "why": "NPV measures expected value added."}, {"topic": "corporate", "q": "Interest expense is normally excluded from project free cash flows when discounting at WACC because financing cost is:", "choices": ["irrelevant", "already reflected in WACC", "always tax-free"], "a": 1, "why": "Including it would double count financing effects."}, {"topic": "corporate", "q": "An increase in days receivables, all else equal, will most likely:", "choices": ["shorten the cash conversion cycle", "lengthen the cash conversion cycle", "have no effect"], "a": 1, "why": "CCC includes receivable days positively."}, {"topic": "corporate", "q": "Greater fixed operating costs, all else equal, generally cause operating leverage to:", "choices": ["increase", "decrease", "become zero"], "a": 0, "why": "Fixed costs magnify changes in operating profit as sales change."}, {"topic": "corporate", "q": "The after-tax cost of debt equals:", "choices": ["rd(1−T)", "rd/(1−T)", "rd+T"], "a": 0, "why": "Interest tax deductibility creates the tax shield."}, {"topic": "corporate", "q": "A project with risk above the firm's average should generally be evaluated using a discount rate that is:", "choices": ["below WACC", "above WACC", "always equal to WACC"], "a": 1, "why": "Higher risk requires a higher appropriate required return."}, {"topic": "corporate", "q": "A board composed entirely of executives may raise concern primarily about:", "choices": ["independence of oversight", "lack of operating knowledge", "excess liquidity"], "a": 0, "why": "Independent oversight can be weakened."}, {"topic": "corporate", "q": "Aggressive working-capital policy typically uses relatively:", "choices": ["more long-term financing and higher liquidity", "less long-term financing and lower liquidity", "no short-term financing"], "a": 1, "why": "Aggressive policy trades lower financing cost for greater liquidity/refinancing risk."}, {"topic": "fsa", "q": "A company sells goods on credit. At the sale date, revenue increases but cash flow from operations:", "choices": ["necessarily increases immediately", "does not necessarily increase immediately", "is classified as financing"], "a": 1, "why": "Cash is not collected at the sale date."}, {"topic": "fsa", "q": "Depreciation is added back to net income under the indirect method because it is:", "choices": ["a financing inflow", "a noncash expense", "an investing outflow in the current period"], "a": 1, "why": "It reduced net income without using current-period cash."}, {"topic": "fsa", "q": "A current ratio above 1 means current assets are:", "choices": ["greater than current liabilities", "less than current liabilities", "equal to equity"], "a": 0, "why": "Current ratio = current assets/current liabilities."}, {"topic": "fsa", "q": "Using average inventory rather than ending inventory in turnover ratios primarily improves:", "choices": ["period matching", "tax deductibility", "audit independence"], "a": 0, "why": "The income-statement flow covers a period and should be matched to an average balance."}, {"topic": "fsa", "q": "Capitalizing a cost rather than expensing it immediately will initially report:", "choices": ["higher assets and higher profit", "lower assets and higher profit", "higher assets and lower profit"], "a": 0, "why": "Expense is deferred and an asset is recognized."}, {"topic": "fsa", "q": "An impairment loss generally causes assets and current-period profit to:", "choices": ["both increase", "both decrease", "remain unchanged"], "a": 1, "why": "The asset is written down and a loss is recognized."}, {"topic": "fsa", "q": "A deferred tax liability commonly arises when tax depreciation is initially:", "choices": ["slower than accounting depreciation", "faster than accounting depreciation", "equal to accounting depreciation forever"], "a": 1, "why": "Faster tax depreciation lowers current tax but creates future taxable amounts."}, {"topic": "fsa", "q": "Diluted EPS includes potential common shares only when they are:", "choices": ["antidilutive", "dilutive", "secured"], "a": 1, "why": "Antidilutive instruments are excluded."}, {"topic": "fsa", "q": "High net income accompanied by persistently weak operating cash flow may indicate:", "choices": ["stronger earnings quality", "a need for closer earnings-quality analysis", "zero credit risk"], "a": 1, "why": "Cash conversion and accrual quality require investigation."}, {"topic": "fsa", "q": "An unmodified audit opinion means the financial statements are presented fairly in material respects; it does not guarantee:", "choices": ["compliance with the reporting framework", "future profitability", "that an audit occurred"], "a": 1, "why": "The opinion is not a guarantee of performance or absence of all fraud."}, {"topic": "equity", "q": "A market order prioritizes:", "choices": ["price certainty", "execution certainty", "dividend income"], "a": 1, "why": "It seeks immediate execution at available prices."}, {"topic": "equity", "q": "A buy limit order sets the:", "choices": ["maximum purchase price", "minimum purchase price", "exact execution price guaranteed"], "a": 0, "why": "The buyer will not pay above the limit."}, {"topic": "equity", "q": "A market-capitalization-weighted index gives more weight to companies with:", "choices": ["higher share price only", "larger equity market value", "higher dividend yield"], "a": 1, "why": "Weight is based on market capitalization."}, {"topic": "equity", "q": "Semi-strong market efficiency states that prices reflect:", "choices": ["past prices only", "all public information", "all public and private information"], "a": 1, "why": "Semi-strong efficiency includes all publicly available information."}, {"topic": "equity", "q": "A competitive advantage creates value only if it supports returns on invested capital that are:", "choices": ["below the cost of capital", "above the cost of capital", "equal to inflation"], "a": 1, "why": "Value is created when returns exceed the opportunity cost of capital."}, {"topic": "equity", "q": "A higher required return in the Gordon model, all else equal, causes value to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 1, "why": "It increases the denominator r−g."}, {"topic": "equity", "q": "Enterprise value is conceptually the value available to:", "choices": ["common shareholders only", "all capital providers", "employees only"], "a": 1, "why": "It reflects the operating asset value before allocation between debt and equity."}, {"topic": "equity", "q": "A scenario-weighted value should use scenario probabilities that:", "choices": ["sum to 100%", "sum to the discount rate", "are all equal"], "a": 0, "why": "They represent a complete probability distribution."}, {"topic": "equity", "q": "A low P/E multiple may reflect:", "choices": ["undervaluation only", "low expected growth or high risk", "guaranteed superior returns"], "a": 1, "why": "Multiples embed growth, risk, profitability, and accounting effects."}, {"topic": "equity", "q": "When valuing a stable dividend-paying firm with constant sustainable growth, the most directly applicable model is:", "choices": ["Gordon growth model", "liquidation model only", "historical-cost model"], "a": 0, "why": "The Gordon model fits stable perpetual dividend growth below required return."}, {"topic": "fixed", "q": "A bond's coupon rate determines its:", "choices": ["contractual coupon payment", "market discount rate", "credit spread"], "a": 0, "why": "Coupon rate × par determines coupon cash flow."}, {"topic": "fixed", "q": "A premium bond has a coupon rate that is generally:", "choices": ["above its yield to maturity", "below its yield to maturity", "zero"], "a": 0, "why": "Higher coupon than required yield produces price above par."}, {"topic": "fixed", "q": "If required yield falls, an option-free bond's price most likely:", "choices": ["falls", "rises", "remains at par"], "a": 1, "why": "Price and yield move inversely."}, {"topic": "fixed", "q": "A longer-duration bond is generally:", "choices": ["less price-sensitive to yield changes", "more price-sensitive to yield changes", "free of reinvestment risk"], "a": 1, "why": "Duration measures first-order price sensitivity."}, {"topic": "fixed", "q": "Positive convexity means the price gain from a yield decline is generally:", "choices": ["smaller than the price loss from an equal rise", "larger than the price loss from an equal rise", "always zero"], "a": 1, "why": "The price–yield curve is convex."}, {"topic": "fixed", "q": "A callable bond most likely experiences price compression when rates:", "choices": ["fall substantially", "rise substantially", "remain unchanged"], "a": 0, "why": "The issuer's call option becomes more valuable."}, {"topic": "fixed", "q": "Credit spread widening, all else equal, most likely causes a corporate bond's price to:", "choices": ["rise", "fall", "remain unchanged"], "a": 1, "why": "A higher required spread raises the discount rate."}, {"topic": "fixed", "q": "Loss given default equals one minus the:", "choices": ["coupon rate", "recovery rate", "default probability"], "a": 1, "why": "LGD = 1 − recovery rate."}, {"topic": "fixed", "q": "Mortgage prepayments tend to accelerate when interest rates:", "choices": ["fall", "rise", "are unrelated to refinancing"], "a": 0, "why": "Borrowers refinance when cheaper funding becomes available."}, {"topic": "fixed", "q": "A forward rate can be interpreted as a rate implied by:", "choices": ["spot rates under no-arbitrage", "coupon rates only", "historical inflation only"], "a": 0, "why": "Forward rates are derived from the spot curve."}, {"topic": "derivatives", "q": "A long call option has maximum loss equal to:", "choices": ["the strike price", "the premium paid", "unlimited loss"], "a": 1, "why": "The holder can let the option expire."}, {"topic": "derivatives", "q": "A short call position has potential loss that is:", "choices": ["limited to premium", "potentially unlimited", "always zero"], "a": 1, "why": "The underlying can rise without a fixed upper bound."}, {"topic": "derivatives", "q": "A put option is in the money at expiration when:", "choices": ["ST > X", "ST < X", "ST = premium"], "a": 1, "why": "The right to sell at X is valuable when market price is below X."}, {"topic": "derivatives", "q": "A forward contract normally has an initial value close to:", "choices": ["zero", "the spot price", "the full notional"], "a": 0, "why": "The delivery price is set so neither side pays at initiation, absent special terms."}, {"topic": "derivatives", "q": "Futures differ from forwards most directly because futures are:", "choices": ["marked to market daily", "always privately negotiated", "free of margin"], "a": 0, "why": "Daily settlement is a key futures feature."}, {"topic": "derivatives", "q": "An interest-rate swap can be viewed conceptually as:", "choices": ["a series of forward contracts", "an equity share", "a physical commodity only"], "a": 0, "why": "Each settlement resembles a forward-rate agreement."}, {"topic": "derivatives", "q": "Higher expected volatility, all else equal, generally causes the value of both calls and puts to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 0, "why": "Option holders benefit from greater dispersion with limited downside."}, {"topic": "derivatives", "q": "Put–call parity is fundamentally based on:", "choices": ["identical expiration payoffs and no-arbitrage", "historical average returns", "accounting book value"], "a": 0, "why": "Portfolios with identical payoffs should have identical prices."}, {"topic": "derivatives", "q": "The intrinsic value of a call before expiration is:", "choices": ["max(0,S−X)", "max(0,X−S)", "premium plus strike"], "a": 0, "why": "Immediate exercise value is the positive difference between spot and strike."}, {"topic": "derivatives", "q": "A protective put combines:", "choices": ["long stock and long put", "short stock and short put", "long call and short stock"], "a": 0, "why": "The put limits downside on the stock."}, {"topic": "alternatives", "q": "Infrequent appraisal-based pricing most likely causes measured return volatility to be:", "choices": ["smoothed downward", "artificially increased", "exactly unbiased"], "a": 0, "why": "Stale and smoothed appraisals understate short-term variation."}, {"topic": "alternatives", "q": "The private-equity J-curve describes:", "choices": ["weak early net returns followed by possible later gains", "constant annual gains", "a bond price–yield curve"], "a": 0, "why": "Fees and immature investments depress early results."}, {"topic": "alternatives", "q": "A higher capitalization rate, all else equal, causes property value to:", "choices": ["rise", "fall", "remain unchanged"], "a": 1, "why": "Value = NOI/cap rate."}, {"topic": "alternatives", "q": "Survivorship bias in a hedge-fund index most likely biases returns:", "choices": ["upward", "downward", "to exactly zero"], "a": 0, "why": "Failed funds are removed, leaving stronger survivors."}, {"topic": "alternatives", "q": "Backfill bias arises when a fund adds:", "choices": ["selected favorable prior returns after joining a database", "future forecasts only", "audited fees only"], "a": 0, "why": "Historical data are often added after good performance."}, {"topic": "alternatives", "q": "Commodity futures return can differ from spot return because of:", "choices": ["roll yield and collateral yield", "dividends only", "book depreciation"], "a": 0, "why": "Futures exposure adds term-structure roll and collateral effects."}, {"topic": "alternatives", "q": "Infrastructure investments often involve:", "choices": ["short-lived assets with no regulation", "long-lived assets and regulatory or concession risk", "only listed common stock"], "a": 1, "why": "Projects are long duration and frequently regulated or concession-based."}, {"topic": "alternatives", "q": "Carried interest is best described as:", "choices": ["a performance-based share of profits", "a custody fee only", "the risk-free rate"], "a": 0, "why": "Managers may receive a share of profits above specified terms."}, {"topic": "alternatives", "q": "Private-market reported returns may be less comparable because of differences in:", "choices": ["valuation timing and methodology", "arithmetic rules", "currency symbols only"], "a": 0, "why": "Valuation discretion and timing affect reported performance."}, {"topic": "alternatives", "q": "Digital-asset custody risk concerns:", "choices": ["control and safekeeping of access credentials/assets", "coupon reinvestment", "inventory turnover"], "a": 0, "why": "Loss, theft, or failure of custody arrangements can impair ownership or access."}, {"topic": "portfolio", "q": "Portfolio expected return is the:", "choices": ["weighted average of asset expected returns", "sum of asset variances", "highest asset return"], "a": 0, "why": "Expected return is linear in portfolio weights."}, {"topic": "portfolio", "q": "Portfolio variance depends importantly on:", "choices": ["covariances among assets", "expected returns only", "number of accounts"], "a": 0, "why": "Co-movement determines diversification."}, {"topic": "portfolio", "q": "Adding an asset with low correlation to an existing portfolio most likely:", "choices": ["improves diversification", "guarantees higher return", "eliminates all risk"], "a": 0, "why": "Low correlation can reduce portfolio variance."}, {"topic": "portfolio", "q": "Beta measures sensitivity to:", "choices": ["systematic market movements", "firm-specific events only", "accounting earnings only"], "a": 0, "why": "Beta is covariance with the market scaled by market variance."}, {"topic": "portfolio", "q": "A security plotting above the security market line has a return that is:", "choices": ["higher than CAPM-required return for its beta", "lower than the risk-free rate by definition", "exactly equal to alpha zero"], "a": 0, "why": "It offers positive alpha relative to CAPM."}, {"topic": "portfolio", "q": "Risk capacity refers to the investor's:", "choices": ["financial ability to bear losses", "emotional preference only", "forecast accuracy"], "a": 0, "why": "Capacity is economic ability; willingness is psychological."}, {"topic": "portfolio", "q": "For an investor with high willingness but low ability to bear risk, the portfolio should generally reflect:", "choices": ["the lower ability", "the higher willingness", "unlimited leverage"], "a": 0, "why": "The more restrictive dimension governs."}, {"topic": "portfolio", "q": "The investment policy statement should normally document:", "choices": ["objectives and constraints", "only past returns", "guaranteed future performance"], "a": 0, "why": "The IPS guides portfolio decisions and accountability."}, {"topic": "portfolio", "q": "Rebalancing restores:", "choices": ["target asset weights", "the highest recent-return asset", "zero transaction costs"], "a": 0, "why": "It brings exposures back toward policy targets."}, {"topic": "portfolio", "q": "The Sharpe ratio measures excess return per unit of:", "choices": ["total volatility", "beta only", "tracking error only"], "a": 0, "why": "The denominator is standard deviation."}, {"topic": "ethics", "q": "When local law is less strict than the professional standard, a member should generally follow:", "choices": ["the stricter professional standard", "local law only in all cases", "the employer's preference"], "a": 0, "why": "Follow the stricter applicable requirement unless doing so violates law."}, {"topic": "ethics", "q": "Information is material when its disclosure would likely:", "choices": ["affect an investor's decision or the security's price", "interest only one employee", "already be fully public"], "a": 0, "why": "Materiality concerns decision or price significance."}, {"topic": "ethics", "q": "Mosaic theory permits use of:", "choices": ["public information plus immaterial nonpublic information", "material nonpublic information", "client-confidential orders"], "a": 0, "why": "Material nonpublic information remains prohibited."}, {"topic": "ethics", "q": "A member receiving additional compensation that may conflict with employer interests should obtain:", "choices": ["written consent from relevant parties", "oral consent from a friend", "no consent if performance is good"], "a": 0, "why": "Written consent allows informed evaluation of the conflict."}, {"topic": "ethics", "q": "Fair dealing requires members to provide clients:", "choices": ["a fair opportunity to act on recommendations", "identical outcomes", "guaranteed simultaneous receipt under all technical conditions"], "a": 0, "why": "The obligation is fair treatment and opportunity, not guaranteed identical results."}, {"topic": "ethics", "q": "A recommendation should have:", "choices": ["a reasonable and adequate basis", "only management's opinion", "a guaranteed target price"], "a": 0, "why": "Diligence and a reasonable basis are required."}, {"topic": "ethics", "q": "A member preparing to leave an employer may generally:", "choices": ["make arrangements that do not misuse records or solicit clients before departure", "take confidential client lists", "delete employer files"], "a": 0, "why": "Preparation is allowed, but loyalty and property duties remain."}, {"topic": "ethics", "q": "Performance presentation should be:", "choices": ["fair, accurate, and complete", "selected to show only winning accounts", "guaranteed"], "a": 0, "why": "Selective or misleading presentation violates professional duties."}, {"topic": "ethics", "q": "A conflict disclosure should be:", "choices": ["prominent and understandable", "hidden in technical footnotes", "made only after a transaction"], "a": 0, "why": "Clients need clear disclosure before relying on advice."}, {"topic": "ethics", "q": "If a supervisor discovers a likely violation, the supervisor should most appropriately:", "choices": ["take reasonable steps to prevent or address it", "ignore it without investigation", "destroy relevant records"], "a": 0, "why": "Supervisory responsibility includes reasonable prevention and remediation."}, {"topic": "quant", "q": "An investment of 1,000 grows to 1,331 in three years. The annual compound return is closest to:", "choices": ["9%", "10%", "11%"], "a": 1, "why": "1,331/1,000 = 1.331 = 1.10^3, so the annual return is 10%.", "losRef": ""}, {"topic": "quant", "q": "If a distribution is positively skewed, the mean is most likely:", "choices": ["less than the median", "greater than the median", "equal to the mode"], "a": 1, "why": "Large positive observations pull the mean to the right, commonly giving mean > median > mode.", "losRef": ""}, {"topic": "quant", "q": "Variance is expressed in:", "choices": ["the original units", "squared units", "unit-free percentages only"], "a": 1, "why": "Variance averages squared deviations; standard deviation returns to the original units.", "losRef": ""}, {"topic": "quant", "q": "Conditional probability P(A|B) is calculated as:", "choices": ["P(A and B)/P(B)", "P(A)/P(B)", "P(B and A)/P(A)"], "a": 0, "why": "By definition, P(A|B)=P(A∩B)/P(B), provided P(B)>0.", "losRef": ""}, {"topic": "quant", "q": "A 95% confidence interval becomes narrower, all else equal, when:", "choices": ["sample size increases", "confidence level increases", "sample variability increases"], "a": 0, "why": "Larger n lowers the standard error; higher confidence or variability widens the interval.", "losRef": ""}, {"topic": "quant", "q": "A Type II error occurs when an analyst:", "choices": ["rejects a true null", "fails to reject a false null", "accepts a true alternative with certainty"], "a": 1, "why": "Type II error is failing to reject a null hypothesis that is actually false.", "losRef": ""}, {"topic": "quant", "q": "The coefficient of determination in a simple regression measures the proportion of variation in:", "choices": ["X explained by Y", "Y explained by X", "the intercept explained by the slope"], "a": 1, "why": "R-squared is the fraction of dependent-variable variation explained by the regression.", "losRef": ""}, {"topic": "quant", "q": "A bootstrap procedure most directly creates samples by:", "choices": ["resampling with replacement from observed data", "drawing only from a normal distribution", "discarding extreme observations"], "a": 0, "why": "Bootstrap samples are repeatedly drawn with replacement from the observed sample.", "losRef": ""}, {"topic": "quant", "q": "When returns are identical in every period, the arithmetic and geometric means are:", "choices": ["equal", "different by the variance", "opposite in sign"], "a": 0, "why": "With no variation, there is no volatility drag, so the two means coincide.", "losRef": ""}, {"topic": "quant", "q": "A covariance of zero implies that two variables:", "choices": ["are independent in all cases", "have no linear co-movement", "must be normally distributed"], "a": 1, "why": "Zero covariance indicates no linear co-movement, but not necessarily independence.", "losRef": ""}, {"topic": "economics", "q": "A movement along a demand curve is caused by a change in:", "choices": ["the good’s own price", "consumer income", "the price of a substitute"], "a": 0, "why": "A change in the good’s own price changes quantity demanded; other factors shift the curve.", "losRef": ""}, {"topic": "economics", "q": "If supply increases while demand is unchanged, equilibrium price will most likely:", "choices": ["rise", "fall", "remain unchanged"], "a": 1, "why": "A rightward supply shift lowers price and raises equilibrium quantity.", "losRef": ""}, {"topic": "economics", "q": "Marginal cost is best defined as the change in total cost from:", "choices": ["producing one additional unit", "increasing all inputs proportionally", "paying fixed costs"], "a": 0, "why": "Marginal cost is the incremental cost of one more unit of output.", "losRef": ""}, {"topic": "economics", "q": "In a monopoly, marginal revenue is typically:", "choices": ["greater than price", "less than price", "always equal to average cost"], "a": 1, "why": "To sell an extra unit, a monopolist generally lowers price, so marginal revenue is below price.", "losRef": ""}, {"topic": "economics", "q": "The GDP deflator is calculated as:", "choices": ["nominal GDP/real GDP × 100", "real GDP/nominal GDP × 100", "CPI/GDP × 100"], "a": 0, "why": "The GDP deflator compares current-price output with constant-price output.", "losRef": ""}, {"topic": "economics", "q": "Stagflation describes the combination of:", "choices": ["high growth and low inflation", "weak growth and high inflation", "budget surplus and currency appreciation"], "a": 1, "why": "Stagflation combines stagnant or weak output with high inflation.", "losRef": ""}, {"topic": "economics", "q": "A fiscal budget deficit occurs when government:", "choices": ["revenue exceeds spending", "spending exceeds revenue", "exports exceed imports"], "a": 1, "why": "A deficit means expenditures are greater than revenues over the period.", "losRef": ""}, {"topic": "economics", "q": "Under covered interest-rate parity, a currency with the higher interest rate tends to trade at a forward:", "choices": ["premium", "discount", "rate equal to spot"], "a": 1, "why": "The higher-interest-rate currency normally trades at a forward discount relative to the lower-rate currency.", "losRef": ""}, {"topic": "economics", "q": "An automatic stabilizer is best exemplified by:", "choices": ["a newly enacted stimulus package", "progressive income taxes and unemployment benefits", "a central-bank open-market operation"], "a": 1, "why": "These mechanisms change automatically with economic activity without new legislation.", "losRef": ""}, {"topic": "economics", "q": "Comparative advantage is based on lower:", "choices": ["absolute production cost only", "opportunity cost", "market price in every country"], "a": 1, "why": "A party has comparative advantage in the activity with the lower opportunity cost.", "losRef": ""}, {"topic": "corporate", "q": "A project has an initial outlay of 100 and a present value of future cash inflows of 112. Its NPV is:", "choices": ["−12", "12", "212"], "a": 1, "why": "NPV = 112 − 100 = 12.", "losRef": ""}, {"topic": "corporate", "q": "IRR is the discount rate that makes project NPV equal to:", "choices": ["zero", "the initial investment", "the cost of equity"], "a": 0, "why": "IRR solves for the rate at which discounted inflows equal the initial outflow.", "losRef": ""}, {"topic": "corporate", "q": "For a normal project, if IRR exceeds the required return, NPV is most likely:", "choices": ["positive", "negative", "undefined"], "a": 0, "why": "For conventional cash flows, IRR above the hurdle rate implies positive NPV.", "losRef": ""}, {"topic": "corporate", "q": "The cost of retained earnings is most closely related to:", "choices": ["the required return on equity", "the after-tax cost of debt", "the dividend paid last year"], "a": 0, "why": "Retained earnings have an opportunity cost equal to shareholders’ required return.", "losRef": ""}, {"topic": "corporate", "q": "Increasing accounts payable days, all else equal, will most likely:", "choices": ["shorten the cash conversion cycle", "lengthen the cash conversion cycle", "increase inventory turnover"], "a": 0, "why": "Payable days are subtracted in the cash conversion cycle.", "losRef": ""}, {"topic": "corporate", "q": "Financial leverage arises primarily from:", "choices": ["fixed financing costs", "variable operating costs", "higher inventory"], "a": 0, "why": "Debt interest and similar fixed financing obligations magnify equity outcomes.", "losRef": ""}, {"topic": "corporate", "q": "A rights issue gives existing shareholders the opportunity to:", "choices": ["buy new shares, often in proportion to current holdings", "sell company bonds to management", "receive guaranteed dividends"], "a": 0, "why": "Rights offerings allow current owners to maintain proportional ownership by purchasing new shares.", "losRef": ""}, {"topic": "corporate", "q": "A share repurchase, all else equal, reduces:", "choices": ["shares outstanding", "enterprise value by the exact repurchase amount in every case", "operating revenue"], "a": 0, "why": "Repurchased shares normally reduce the number of shares outstanding.", "losRef": ""}, {"topic": "corporate", "q": "A stakeholder-oriented governance model explicitly considers:", "choices": ["only common shareholders", "multiple parties affected by the company", "only senior management"], "a": 1, "why": "Stakeholder governance considers employees, customers, creditors, communities, and owners.", "losRef": ""}, {"topic": "corporate", "q": "A positive externality from a project is a benefit received by:", "choices": ["a third party not fully reflected in market prices", "only the project sponsor", "the tax authority by definition"], "a": 0, "why": "Externalities affect parties outside the direct transaction and may not be fully priced.", "losRef": ""}, {"topic": "fsa", "q": "The accounting equation is:", "choices": ["Assets = Liabilities + Equity", "Revenue = Assets + Expenses", "Cash = Debt + Profit"], "a": 0, "why": "The balance sheet is structured around assets financed by liabilities and owners’ equity.", "losRef": ""}, {"topic": "fsa", "q": "Gross profit equals revenue minus:", "choices": ["cost of goods sold", "operating expenses and tax", "interest expense only"], "a": 0, "why": "Gross profit is sales less the direct cost of goods sold.", "losRef": ""}, {"topic": "fsa", "q": "If ending inventory is overstated, current-period cost of goods sold is most likely:", "choices": ["overstated", "understated", "unchanged"], "a": 1, "why": "COGS = beginning inventory + purchases − ending inventory; overstating ending inventory understates COGS.", "losRef": ""}, {"topic": "fsa", "q": "An increase in an operating liability under the indirect cash-flow method is generally:", "choices": ["added to net income", "subtracted from net income", "classified as investing"], "a": 0, "why": "The company recognized expense without yet paying cash, preserving operating cash.", "losRef": ""}, {"topic": "fsa", "q": "Free cash flow to the firm is cash flow available to:", "choices": ["all capital providers", "common shareholders only", "tax authorities only"], "a": 0, "why": "FCFF is available to debt and equity providers after operating and investment needs.", "losRef": ""}, {"topic": "fsa", "q": "A common-size income statement expresses each line item as a percentage of:", "choices": ["revenue", "total assets", "equity"], "a": 0, "why": "Income-statement common sizing normally uses revenue as the denominator.", "losRef": ""}, {"topic": "fsa", "q": "A common-size balance sheet expresses each item as a percentage of:", "choices": ["total assets", "revenue", "net income"], "a": 0, "why": "Balance-sheet common sizing normally uses total assets.", "losRef": ""}, {"topic": "fsa", "q": "A decline in receivables turnover most likely indicates that collection has become:", "choices": ["faster", "slower", "irrelevant"], "a": 1, "why": "Lower turnover generally means receivables remain outstanding longer.", "losRef": ""}, {"topic": "fsa", "q": "ROA is commonly calculated as net income divided by:", "choices": ["average total assets", "ending revenue", "average current liabilities"], "a": 0, "why": "Using average assets matches the period flow of income with the average resource base.", "losRef": ""}, {"topic": "fsa", "q": "A permanent tax difference affects the effective tax rate but generally does not create a:", "choices": ["deferred tax asset or liability", "current tax expense", "difference between statutory and effective rates"], "a": 0, "why": "Permanent differences never reverse, so they do not create deferred tax balances.", "losRef": ""}, {"topic": "equity", "q": "The bid price is the highest price at which a dealer or investor is willing to:", "choices": ["buy", "sell", "short only"], "a": 0, "why": "The bid is the buying price; the ask is the selling price.", "losRef": ""}, {"topic": "equity", "q": "The bid–ask spread is generally narrower for securities that are:", "choices": ["more liquid", "less frequently traded", "more opaque"], "a": 0, "why": "Greater liquidity and competition usually reduce trading spreads.", "losRef": ""}, {"topic": "equity", "q": "A primary-market transaction occurs when:", "choices": ["an issuer sells newly created securities", "investors trade existing shares", "an index is rebalanced"], "a": 0, "why": "Primary markets provide capital to issuers through new security issuance.", "losRef": ""}, {"topic": "equity", "q": "An equal-weighted index requires periodic rebalancing mainly because:", "choices": ["relative prices change", "all companies issue identical dividends", "market capitalizations never change"], "a": 0, "why": "Price movements alter weights, so the index must trade back to equal weights.", "losRef": ""}, {"topic": "equity", "q": "Fundamental analysis is primarily concerned with estimating:", "choices": ["intrinsic value", "the next trade’s bid–ask spread only", "historical volatility only"], "a": 0, "why": "Fundamental analysis evaluates economic and financial drivers of intrinsic value.", "losRef": ""}, {"topic": "equity", "q": "A firm with sustainable ROE above its required return creates more value when it:", "choices": ["reinvests profitable earnings", "distributes all earnings regardless of opportunities", "increases leverage without limit"], "a": 0, "why": "Reinvestment at returns above the required return adds value.", "losRef": ""}, {"topic": "equity", "q": "A two-stage dividend model is most appropriate when growth is expected to be:", "choices": ["high initially and stable later", "constant forever from today", "negative forever"], "a": 0, "why": "The model captures a finite high-growth stage followed by stable growth.", "losRef": ""}, {"topic": "equity", "q": "Price-to-book is often most informative for firms whose assets are:", "choices": ["measurable and closely related to value", "mostly unrecorded intangible options", "irrelevant to operations"], "a": 0, "why": "Book value is more meaningful when recorded net assets approximate economic capital.", "losRef": ""}, {"topic": "equity", "q": "A cyclical company’s earnings are most likely to be highly sensitive to:", "choices": ["the business cycle", "the day of dividend payment only", "par value"], "a": 0, "why": "Cyclical demand and margins move strongly with economic conditions.", "losRef": ""}, {"topic": "equity", "q": "A research report should clearly distinguish:", "choices": ["facts from opinions", "market prices from trading volume only", "dividends from interest only"], "a": 0, "why": "Clear communication separates factual inputs, assumptions, analysis, and conclusions.", "losRef": ""}, {"topic": "fixed", "q": "A zero-coupon bond pays:", "choices": ["no periodic coupons", "no principal at maturity", "a floating coupon every month"], "a": 0, "why": "It is issued at a discount and pays par at maturity without periodic coupons.", "losRef": ""}, {"topic": "fixed", "q": "A bond trading below par is a:", "choices": ["discount bond", "premium bond", "perpetuity by definition"], "a": 0, "why": "Price below face value means the bond trades at a discount.", "losRef": ""}, {"topic": "fixed", "q": "Yield to maturity assumes coupon cash flows are reinvested at approximately the:", "choices": ["yield to maturity", "coupon rate only", "risk-free rate only"], "a": 0, "why": "The conventional YTM interpretation assumes reinvestment at the YTM.", "losRef": ""}, {"topic": "fixed", "q": "Reinvestment risk is greatest for a bond with:", "choices": ["large interim coupons", "no cash flows before maturity", "a zero coupon"], "a": 0, "why": "More interim cash flows create more exposure to future reinvestment rates.", "losRef": ""}, {"topic": "fixed", "q": "Price risk and reinvestment risk generally move:", "choices": ["in opposite directions as horizon changes", "always in the same direction", "independently of interest rates"], "a": 0, "why": "Rising rates hurt price but improve coupon reinvestment, and vice versa.", "losRef": ""}, {"topic": "fixed", "q": "Macaulay duration is expressed in:", "choices": ["years", "percentage points", "currency units"], "a": 0, "why": "Macaulay duration is a weighted-average time to receipt of cash flows.", "losRef": ""}, {"topic": "fixed", "q": "A putable bond gives the option to:", "choices": ["the investor", "the issuer", "the trustee only"], "a": 0, "why": "The investor may sell the bond back under specified conditions.", "losRef": ""}, {"topic": "fixed", "q": "A senior secured bond generally has expected recovery that is:", "choices": ["higher than a subordinated unsecured bond", "lower than all equity", "exactly 100%"], "a": 0, "why": "Priority and collateral generally improve recovery prospects.", "losRef": ""}, {"topic": "fixed", "q": "A mortgage-backed security investor faces contraction risk when prepayments are:", "choices": ["faster than expected", "slower than expected", "legally prohibited"], "a": 0, "why": "Fast prepayments return principal sooner, shortening the investment horizon.", "losRef": ""}, {"topic": "fixed", "q": "The par curve gives coupon rates that make newly issued bonds price at:", "choices": ["par", "zero", "a deep discount"], "a": 0, "why": "Each par yield is the coupon rate for a bond priced at face value.", "losRef": ""}, {"topic": "derivatives", "q": "The long side of a forward contract agrees to:", "choices": ["buy the underlying at expiration", "sell the underlying at expiration", "pay only an option premium"], "a": 0, "why": "The long commits to purchase at the delivery price.", "losRef": ""}, {"topic": "derivatives", "q": "A short forward gains when the spot price at expiration is:", "choices": ["below the delivery price", "above the delivery price", "equal to the initial spot regardless of K"], "a": 0, "why": "Short-forward payoff is K−ST.", "losRef": ""}, {"topic": "derivatives", "q": "An option’s time value equals option value minus:", "choices": ["intrinsic value", "strike price", "spot price"], "a": 0, "why": "Option premium consists of intrinsic value plus time value.", "losRef": ""}, {"topic": "derivatives", "q": "A call option is out of the money when:", "choices": ["S < X", "S > X", "S = X plus premium"], "a": 0, "why": "Immediate exercise would have no positive value when spot is below strike.", "losRef": ""}, {"topic": "derivatives", "q": "A put option’s value generally increases when the underlying price:", "choices": ["falls", "rises", "becomes equal to zero volatility"], "a": 0, "why": "The right to sell at a fixed strike becomes more valuable as spot declines.", "losRef": ""}, {"topic": "derivatives", "q": "A covered call consists of:", "choices": ["long stock and short call", "short stock and long call", "long put and short bond"], "a": 0, "why": "The stock covers the obligation created by the written call.", "losRef": ""}, {"topic": "derivatives", "q": "A fiduciary call consists of a long call plus:", "choices": ["a risk-free bond paying the strike at expiration", "a short stock position", "a long put"], "a": 0, "why": "The bond supplies the exercise price; together they replicate a protective put.", "losRef": ""}, {"topic": "derivatives", "q": "At initiation, a fairly priced swap has a value closest to:", "choices": ["zero", "the notional amount", "the first payment"], "a": 0, "why": "Terms are set so the present values of the two legs are equal.", "losRef": ""}, {"topic": "derivatives", "q": "Initial margin in futures is best viewed as:", "choices": ["performance collateral", "a down payment on the underlying", "an option premium"], "a": 0, "why": "It secures performance and is adjusted through daily settlement.", "losRef": ""}, {"topic": "derivatives", "q": "Basis is commonly defined as the difference between:", "choices": ["spot and futures prices", "call and put premiums only", "coupon and yield"], "a": 0, "why": "Basis links cash and futures markets and typically converges near expiration.", "losRef": ""}, {"topic": "alternatives", "q": "Private equity investments are generally less liquid than listed equities because they:", "choices": ["lack continuous public trading", "pay no cash flows by definition", "have no legal ownership"], "a": 0, "why": "Private interests are negotiated and do not trade continuously on public exchanges.", "losRef": ""}, {"topic": "alternatives", "q": "A leveraged buyout uses substantial:", "choices": ["debt financing", "central-bank reserves", "commodity inventory only"], "a": 0, "why": "Debt is commonly used to finance the acquisition and amplify equity returns and risk.", "losRef": ""}, {"topic": "alternatives", "q": "Net operating income for property valuation is generally measured before:", "choices": ["financing costs and income tax", "rental revenue", "property operating expenses"], "a": 0, "why": "NOI reflects property operations before capital structure and tax effects.", "losRef": ""}, {"topic": "alternatives", "q": "A hedge fund using long and short positions to reduce broad market exposure is most likely pursuing:", "choices": ["relative-value or equity market-neutral features", "pure long-only indexing", "insured deposit taking"], "a": 0, "why": "Offsetting longs and shorts can reduce market beta while targeting relative mispricing.", "losRef": ""}, {"topic": "alternatives", "q": "A lockup period restricts an investor’s ability to:", "choices": ["redeem capital for a specified period", "receive performance reports", "pay management fees"], "a": 0, "why": "Lockups improve strategy funding stability but reduce investor liquidity.", "losRef": ""}, {"topic": "alternatives", "q": "Contango exists when futures prices are generally:", "choices": ["above spot for later maturities", "below spot for later maturities", "equal to book value"], "a": 0, "why": "An upward-sloping futures curve is commonly described as contango.", "losRef": ""}, {"topic": "alternatives", "q": "For a long-only futures position, negative roll yield commonly occurs in:", "choices": ["contango", "backwardation", "a flat spot market only"], "a": 0, "why": "Rolling from a cheaper expiring contract into a more expensive later contract creates a drag.", "losRef": ""}, {"topic": "alternatives", "q": "Infrastructure revenue may be linked to inflation through:", "choices": ["contractual tariff adjustments", "equity dilution only", "inventory accounting"], "a": 0, "why": "Many regulated or contracted assets include inflation-linked pricing terms.", "losRef": ""}, {"topic": "alternatives", "q": "Operational due diligence focuses most directly on:", "choices": ["processes, controls, service providers, and governance", "only expected market return", "only asset beta"], "a": 0, "why": "Operational failures can cause loss independently of investment strategy.", "losRef": ""}, {"topic": "alternatives", "q": "A digital token’s price may be affected by network adoption, but valuation remains difficult partly because:", "choices": ["cash-flow rights may be unclear or absent", "all tokens pay fixed coupons", "volatility is always zero"], "a": 0, "why": "Many tokens lack conventional contractual cash flows, complicating intrinsic valuation.", "losRef": ""}, {"topic": "portfolio", "q": "The minimum-variance frontier contains portfolios that have the lowest variance for each level of:", "choices": ["expected return", "beta only", "dividend yield"], "a": 0, "why": "It is the lower-risk boundary of feasible portfolios for given expected returns.", "losRef": ""}, {"topic": "portfolio", "q": "The efficient frontier is the portion of the minimum-variance frontier offering:", "choices": ["maximum expected return for a given risk", "minimum return for a given risk", "only risk-free portfolios"], "a": 0, "why": "Efficient portfolios dominate alternatives on the risk–return trade-off.", "losRef": ""}, {"topic": "portfolio", "q": "The capital allocation line combines a risky portfolio with:", "choices": ["a risk-free asset", "only another risky stock", "a commodity future only"], "a": 0, "why": "It represents combinations of the risk-free asset and a selected risky portfolio.", "losRef": ""}, {"topic": "portfolio", "q": "The slope of the capital allocation line is the risky portfolio’s:", "choices": ["Sharpe ratio", "beta", "duration"], "a": 0, "why": "Slope = excess expected return divided by standard deviation.", "losRef": ""}, {"topic": "portfolio", "q": "Unsystematic risk is also called:", "choices": ["idiosyncratic risk", "market risk", "inflation risk"], "a": 0, "why": "It is issuer- or asset-specific and diversifiable.", "losRef": ""}, {"topic": "portfolio", "q": "A risk-averse investor requires higher expected return for:", "choices": ["higher risk", "lower risk", "shorter reports"], "a": 0, "why": "Risk aversion implies compensation is required for accepting more uncertainty.", "losRef": ""}, {"topic": "portfolio", "q": "An endowment with a long horizon and low near-term spending needs may generally have:", "choices": ["greater ability to accept illiquidity", "no need for an IPS", "zero risk capacity"], "a": 0, "why": "Long horizon and limited liquidity demands can support illiquid allocations, subject to other constraints.", "losRef": ""}, {"topic": "portfolio", "q": "Tracking error measures the variability of:", "choices": ["active return relative to a benchmark", "total portfolio return only", "risk-free return"], "a": 0, "why": "It is the standard deviation of portfolio return minus benchmark return.", "losRef": ""}, {"topic": "portfolio", "q": "Value at Risk estimates a loss threshold for a specified:", "choices": ["probability and time horizon", "accounting year only", "coupon rate"], "a": 0, "why": "VaR is conditional on confidence level, horizon, and model assumptions.", "losRef": ""}, {"topic": "portfolio", "q": "Risk budgeting allocates acceptable risk across:", "choices": ["assets, strategies, or managers", "only cash accounts", "historical accounting periods"], "a": 0, "why": "It links total risk tolerance to component risk contributions.", "losRef": ""}, {"topic": "ethics", "q": "A member must maintain independence and objectivity when receiving:", "choices": ["gifts or benefits that could influence judgment", "only salary from the employer", "publicly available data"], "a": 0, "why": "Benefits that could compromise judgment require avoidance, consent, or disclosure as applicable.", "losRef": ""}, {"topic": "ethics", "q": "Plagiarism is a form of:", "choices": ["misrepresentation", "fair dealing", "suitability analysis"], "a": 0, "why": "Presenting another’s work as one’s own misrepresents authorship.", "losRef": ""}, {"topic": "ethics", "q": "Market manipulation includes transactions intended to:", "choices": ["mislead market participants about price or volume", "implement a legitimate client order", "rebalance an index transparently"], "a": 0, "why": "Artificial price or volume signals undermine market integrity.", "losRef": ""}, {"topic": "ethics", "q": "Client confidentiality may generally be broken when:", "choices": ["required by law", "a colleague is curious", "the information could improve marketing"], "a": 0, "why": "Legal requirements can override confidentiality; other limited exceptions may also apply under the Standards.", "losRef": ""}, {"topic": "ethics", "q": "Suitability requires an adviser to consider the client’s:", "choices": ["objectives, constraints, and total portfolio", "favorite security only", "employer’s revenue target"], "a": 0, "why": "Recommendations must fit the client’s circumstances and portfolio context.", "losRef": ""}, {"topic": "ethics", "q": "Priority of transactions generally requires client and employer transactions to take precedence over:", "choices": ["personal transactions", "public market data", "regulatory filings"], "a": 0, "why": "Members should not benefit personally ahead of clients or employers.", "losRef": ""}, {"topic": "ethics", "q": "Referral fees should be disclosed to:", "choices": ["the client or prospective client as appropriate", "no one if legal", "only the referral source"], "a": 0, "why": "Disclosure enables assessment of potential conflicts and cost.", "losRef": ""}, {"topic": "ethics", "q": "Records supporting investment recommendations should generally be maintained by:", "choices": ["the firm or member according to applicable duties and policy", "the issuer only", "the exchange only"], "a": 0, "why": "Adequate records support diligence, communication, and supervision.", "losRef": ""}, {"topic": "ethics", "q": "A member who suspects a colleague violated the law should first avoid:", "choices": ["participating in or assisting the violation", "documenting concerns", "seeking appropriate guidance"], "a": 0, "why": "The member must dissociate from illegal or unethical activity and take appropriate steps.", "losRef": ""}, {"topic": "ethics", "q": "Using the CFA designation as a noun to imply a superior type of person is:", "choices": ["improper use of the designation", "required marketing", "acceptable if performance is strong"], "a": 0, "why": "The designation must be used as an adjective and not exaggerated or misrepresented.", "losRef": ""}, {"topic": "fsa", "q": "The first step in a financial statement analysis framework is to:", "choices": ["calculate ratios", "define the purpose and context", "adjust accounting data"], "a": 1, "why": "The analytical question, audience, horizon, and context determine the data and methods required.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Which source most likely explains significant accounting estimates and commitments?", "choices": ["Financial statement notes", "Share-price chart", "Marketing brochure"], "a": 0, "why": "Notes provide policy, estimate, commitment, contingency, and risk details.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "An unmodified audit opinion most directly indicates that the statements:", "choices": ["guarantee future solvency", "are presented fairly in material respects under the framework", "contain no fraud of any size"], "a": 1, "why": "The opinion provides reasonable assurance about fair presentation, not guarantees of performance or complete fraud absence.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "For short-term credit analysis, the most relevant emphasis is usually:", "choices": ["brand value over 20 years", "liquidity and near-term debt service", "long-run equity terminal value"], "a": 1, "why": "A short-term lender focuses on cash availability and repayment capacity.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Management commentary is particularly useful for understanding:", "choices": ["strategy and management's view of drivers", "the independent audit opinion", "only historical tax payments"], "a": 0, "why": "Management commentary discusses strategy, risks, trends, and outlook, though it may be biased.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "When two firms apply different acceptable accounting policies, an analyst should most appropriately:", "choices": ["ignore the difference", "consider transparent comparability adjustments", "replace both statements with market prices"], "a": 1, "why": "Policy differences can distort comparisons and may require supported adjustments.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Which is an external information source?", "choices": ["Competitor regulatory filing", "The company's balance sheet", "The company's footnotes"], "a": 0, "why": "A competitor filing is external to the analyzed company.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "A qualified audit opinion should cause the analyst to:", "choices": ["automatically value equity at zero", "understand the scope and financial effect of the qualification", "ignore all remaining disclosures"], "a": 1, "why": "The nature and materiality of the issue must be assessed.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "The follow-up step in analysis primarily involves:", "choices": ["monitoring changes and updating conclusions", "deleting prior assumptions", "stopping after report delivery"], "a": 0, "why": "Analysis is ongoing as new information becomes available.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Regulatory filings can be more useful than a glossy annual report because they often contain:", "choices": ["required standardized disclosures", "guaranteed forecasts", "only advertising"], "a": 0, "why": "Regulatory filings provide mandated and often detailed information.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "A key limitation of ratio analysis is that ratios:", "choices": ["never permit comparisons", "can be affected by accounting policies and business models", "are always based on cash"], "a": 1, "why": "Ratios require context and comparability assessment.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "The analytical process should be documented primarily to:", "choices": ["support consistency and defensible conclusions", "hide assumptions", "avoid future updates"], "a": 0, "why": "Documentation improves reproducibility, review, and accountability.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Key audit matters most appropriately:", "choices": ["identify areas of significant audit attention", "replace the notes", "predict bankruptcy"], "a": 0, "why": "They highlight significant judgment areas but are not predictions.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Which action belongs to processing data?", "choices": ["Reclassifying items for comparability", "Defining the decision question", "Presenting the final recommendation"], "a": 0, "why": "Processing includes organizing, calculating, and adjusting data.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Industry data are most useful for:", "choices": ["providing context and peer benchmarks", "proving management fraud", "eliminating accounting differences"], "a": 0, "why": "Industry data help assess relative performance and structural norms.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Revenue recognized before cash collection most directly increases:", "choices": ["revenue and a receivable or contract asset", "cash and debt", "inventory and dividends"], "a": 0, "why": "Credit revenue creates an asset until collection.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Capitalizing an eligible cost instead of expensing it immediately initially causes profit to be:", "choices": ["higher", "lower", "unchanged in all cases"], "a": 0, "why": "Capitalization defers expense recognition.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Basic EPS denominator uses:", "choices": ["ending common shares", "weighted-average common shares", "authorized shares"], "a": 1, "why": "Weighted average reflects shares outstanding during the period.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Antidilutive securities are:", "choices": ["included in diluted EPS", "excluded from diluted EPS", "included in basic EPS denominator"], "a": 1, "why": "Including them would increase EPS or reduce loss per share, so they are excluded.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "A common-size income statement normally expresses items as a percentage of:", "choices": ["total assets", "revenue", "equity"], "a": 1, "why": "Revenue is the standard base.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Gross margin is calculated as:", "choices": ["gross profit/revenue", "operating profit/assets", "net income/equity"], "a": 0, "why": "Gross margin measures gross profit per unit of revenue.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "A gain on sale of equipment should be assessed as:", "choices": ["necessarily recurring operating revenue", "potentially nonrecurring and nonoperating", "a financing cash inflow"], "a": 1, "why": "It is generally not a core revenue source and its cash proceeds are investing.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Expensing a cost immediately compared with capitalization initially results in:", "choices": ["lower assets and lower profit", "higher assets and lower profit", "lower liabilities and higher profit"], "a": 0, "why": "The expense reduces profit and no asset is recognized.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "If revenue grows 8% and receivables grow 30%, an analyst should most likely investigate:", "choices": ["collection and revenue-recognition quality", "debt maturity only", "share repurchases only"], "a": 0, "why": "Receivables growing much faster than sales can signal weaker collection or aggressive recognition.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Net margin includes the effects of:", "choices": ["only production costs", "operating, financing, nonoperating, and tax items", "only dividends"], "a": 1, "why": "Net income reflects the full income statement.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "A restructuring charge described as 'one-time' should be removed from normalized earnings:", "choices": ["automatically", "only after assessing recurrence and economic relevance", "never"], "a": 1, "why": "Some firms repeatedly incur restructuring costs.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Diluted EPS is generally:", "choices": ["greater than or equal to basic EPS", "less than or equal to basic EPS for profitable firms", "unrelated to potential shares"], "a": 1, "why": "Dilutive securities reduce EPS; antidilutive instruments are excluded.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "If weighted-average shares rise while income available to common is unchanged, basic EPS:", "choices": ["rises", "falls", "is unchanged"], "a": 1, "why": "The denominator increases.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "An impairment charge most directly causes current profit and assets to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 1, "why": "The asset is written down and a loss is recognized.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Operating margin differs from gross margin because operating margin also reflects:", "choices": ["operating expenses", "dividends", "share issuance"], "a": 0, "why": "Operating profit subtracts operating costs beyond COGS.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Goodwill is most commonly created by:", "choices": ["organic advertising", "a business combination", "paying a dividend"], "a": 1, "why": "Goodwill arises when acquisition consideration exceeds recognized identifiable net assets.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "A finite-lived intangible asset is generally:", "choices": ["amortized over its useful life", "never expensed", "recorded as revenue"], "a": 0, "why": "Finite-lived intangibles are amortized and tested for impairment as applicable.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "A large goodwill balance relative to equity most likely indicates:", "choices": ["significant acquisition-related asset exposure", "high cash holdings", "no impairment risk"], "a": 0, "why": "Goodwill reflects acquisition premiums and can expose equity to impairment.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "The quick ratio differs from the current ratio mainly by excluding:", "choices": ["cash", "inventory", "current liabilities"], "a": 1, "why": "Quick assets generally exclude inventory and sometimes other less-liquid current assets.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "A receivables balance growing faster than revenue may indicate:", "choices": ["improving cash collection", "potential collection or recognition concerns", "lower credit sales"], "a": 1, "why": "The relationship can signal slower collections or aggressive revenue recognition.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "A debt maturity schedule is important primarily for assessing:", "choices": ["refinancing and liquidity risk", "gross margin", "inventory obsolescence"], "a": 0, "why": "Concentrated near-term maturities can create funding pressure.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "Internally generated brand value is often:", "choices": ["fully recognized at market value", "not recognized even though economically valuable", "classified as cash"], "a": 1, "why": "Recognition rules can omit internally generated economic assets.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "Book value of equity is best described as:", "choices": ["always equal to market capitalization", "an accounting residual that may differ materially from market value", "the present value of all dividends"], "a": 1, "why": "Book and market values use different measurement bases.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "An increase in the allowance for doubtful accounts most directly:", "choices": ["reduces net receivables", "increases cash", "reduces debt"], "a": 0, "why": "The contra-asset lowers receivables' carrying amount.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "Fair-value measurement generally makes reported amounts more sensitive to:", "choices": ["current market assumptions", "historical payroll only", "authorized shares"], "a": 0, "why": "Fair value reflects market-based inputs and valuation estimates.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "Noncurrent liabilities include obligations such as:", "choices": ["long-term debt and pension obligations", "cash and inventory", "revenue and COGS"], "a": 0, "why": "They are obligations due beyond the current classification period.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "If current assets are 300 and current liabilities 200, the current ratio is:", "choices": ["0.67", "1.50", "2.00"], "a": 1, "why": "300/200 = 1.50.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "If an acquisition price is 450 and identifiable net assets are 390, goodwill is:", "choices": ["60", "390", "840"], "a": 0, "why": "450−390 = 60.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "A common-size increase in debt from 25% to 40% of assets most directly suggests:", "choices": ["greater balance-sheet leverage", "lower revenue", "higher inventory turnover"], "a": 0, "why": "Debt finances a larger share of assets.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "Under the indirect method, an increase in inventory is:", "choices": ["added to net income", "subtracted from net income", "classified as financing"], "a": 1, "why": "An operating asset increase uses cash.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Under the indirect method, an increase in accounts payable is:", "choices": ["added to net income", "subtracted from net income", "ignored"], "a": 0, "why": "An operating liability increase preserves cash.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Depreciation is added back to net income because it is:", "choices": ["a noncash expense", "an investing inflow", "a financing outflow"], "a": 0, "why": "It reduced profit without current cash use.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "A gain on sale of equipment is subtracted in indirect CFO because:", "choices": ["sale proceeds belong in investing and the gain increased net income", "it reduced net income", "it is a financing item"], "a": 0, "why": "The gain must be removed from CFO to avoid double counting.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "The direct method reports:", "choices": ["cash collected and cash paid by major operating category", "only net income adjustments", "only financing flows"], "a": 0, "why": "It presents gross operating cash receipts and payments.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Correctly prepared direct and indirect methods produce CFO that is:", "choices": ["different", "the same", "always zero"], "a": 1, "why": "Only presentation differs.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Buying equipment for cash is classified as:", "choices": ["operating", "investing", "financing"], "a": 1, "why": "It is acquisition of a long-term asset.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Issuing common shares for cash is classified as:", "choices": ["operating", "investing", "financing"], "a": 2, "why": "It is a transaction with capital providers.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Cash collected from customers equals sales adjusted for the change in:", "choices": ["receivables", "debt", "PPE"], "a": 0, "why": "Credit sales not collected remain in receivables.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "If receivables decrease, cash collected from customers is generally:", "choices": ["less than sales", "greater than sales", "equal to zero"], "a": 1, "why": "Collections include prior-period receivables.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "If inventory increases and payables are unchanged, cash paid to suppliers is generally:", "choices": ["less than COGS", "greater than COGS", "equal to dividends"], "a": 1, "why": "Purchases exceed COGS when inventory builds.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Under US GAAP, dividends paid are generally classified as:", "choices": ["operating", "investing", "financing"], "a": 2, "why": "US GAAP classifies dividends paid as financing.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Under IFRS, classification of interest paid may be:", "choices": ["operating or financing, applied consistently", "investing only", "never disclosed"], "a": 0, "why": "IFRS permits a policy choice under the applicable rules.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "A decrease in an operating liability is an indirect CFO adjustment that is:", "choices": ["positive", "negative", "always noncash"], "a": 1, "why": "Paying down the liability uses cash.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "The cash-flow statement reconciles:", "choices": ["beginning and ending cash", "beginning and ending revenue", "gross and net margin"], "a": 0, "why": "It explains the period's cash change.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "FCFF represents cash available to:", "choices": ["common equity only", "all capital providers", "employees only"], "a": 1, "why": "FCFF is available to debt and equity capital providers.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "FCFE represents cash available to:", "choices": ["common equity after investment and net borrowing", "all creditors before tax", "suppliers only"], "a": 0, "why": "FCFE is the residual available to common equity.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "When deriving FCFF from CFO and interest is included in CFO, add back:", "choices": ["after-tax interest", "full debt principal", "dividends"], "a": 0, "why": "Interest is added after tax because FCFF is pre-financing but after-tax.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "Net borrowing equals:", "choices": ["debt issued minus debt repaid", "interest minus tax", "CFO minus revenue"], "a": 0, "why": "It measures net new debt financing.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "A persistent excess of net income over CFO may warrant concern about:", "choices": ["earnings cash conversion", "share authorization", "only tax rates"], "a": 0, "why": "Sustained accrual build-up may weaken earnings quality.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "CFO margin is:", "choices": ["CFO/revenue", "CFO/assets only", "revenue/CFO"], "a": 0, "why": "It measures operating cash generated per unit of revenue.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "Negative investing cash flow caused by productive capital expenditure is:", "choices": ["automatically bad", "not automatically bad", "always financing"], "a": 1, "why": "Investment may support growth and future cash flow.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "If CFO is 300 and capex 120, before financing adjustments cash after capex is:", "choices": ["180", "420", "120"], "a": 0, "why": "300−120 = 180.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "If debt issued is 80 and repaid is 50, net borrowing is:", "choices": ["30", "130", "−30"], "a": 0, "why": "80−50 = 30.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "If CFO is 200, capex 70, and net borrowing 20, FCFE is:", "choices": ["110", "150", "290"], "a": 1, "why": "200−70+20 = 150.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "If CFO is 200, after-tax interest 15, and capex 70, FCFF is:", "choices": ["115", "145", "285"], "a": 1, "why": "200+15−70 = 145.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "Common-size cash-flow analysis most often scales cash flows by:", "choices": ["revenue or another consistent base", "authorized shares only", "the audit fee"], "a": 0, "why": "A consistent base reveals structural trends.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "CFO-to-debt is primarily a measure of:", "choices": ["cash debt-servicing capacity", "gross profitability", "inventory age"], "a": 0, "why": "It relates operating cash generation to debt obligations.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "A rising CFO margin with stable revenue most likely indicates:", "choices": ["improved operating cash generation", "lower cash generation", "automatic fraud"], "a": 0, "why": "More cash is generated per unit of revenue.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "FCFF and FCFE calculations should be interpreted carefully because:", "choices": ["classification and starting-point definitions can differ", "cash flow is never useful", "taxes do not matter"], "a": 0, "why": "The exact formula depends on the available data and classification choices.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "In a period of rising purchase prices, FIFO compared with weighted average most likely reports:", "choices": ["higher COGS", "higher ending inventory", "lower gross profit"], "a": 1, "why": "FIFO leaves more recent, higher costs in ending inventory.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "Under IFRS, use of LIFO for inventory costing is:", "choices": ["required", "permitted", "prohibited"], "a": 2, "why": "IFRS prohibits LIFO.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "A LIFO reserve is most useful for converting LIFO inventory approximately to:", "choices": ["FIFO inventory", "cash inventory", "replacement revenue"], "a": 0, "why": "FIFO inventory is approximately LIFO inventory plus the LIFO reserve.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "If the LIFO reserve increases during the year, FIFO COGS compared with LIFO COGS is generally:", "choices": ["higher", "lower", "identical"], "a": 1, "why": "FIFO COGS ≈ LIFO COGS minus the increase in the reserve.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "An inventory write-down initially causes:", "choices": ["assets and profit to decrease", "assets to rise and profit to fall", "cash to decrease immediately"], "a": 0, "why": "The write-down reduces inventory and recognizes expense or loss.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "Under IFRS, a prior inventory write-down may be reversed when:", "choices": ["value subsequently recovers, within limits", "management changes auditors", "sales volume falls"], "a": 0, "why": "IFRS permits reversal up to the original write-down when circumstances improve.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "Inventory turnover is normally calculated as:", "choices": ["sales/average inventory", "COGS/average inventory", "average inventory/COGS"], "a": 1, "why": "COGS is matched with average inventory.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "Days inventory on hand is most directly derived from:", "choices": ["365/inventory turnover", "inventory turnover/365", "sales/current assets"], "a": 0, "why": "Days inventory = 365 divided by inventory turnover.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "A falling inventory turnover combined with stable sales may indicate:", "choices": ["inventory accumulation or obsolescence", "faster inventory movement", "lower average inventory"], "a": 0, "why": "Lower turnover can indicate slower movement or excess stock.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "During rising prices, FIFO compared with LIFO normally results in:", "choices": ["lower taxes", "higher taxes", "identical taxes"], "a": 1, "why": "FIFO generally reports higher profit and therefore higher taxes.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "Which cost is most likely included in inventory?", "choices": ["Abnormal waste", "Cost to bring goods to present condition", "General selling expense"], "a": 1, "why": "Inventory includes necessary purchase and conversion costs.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "A write-down of inventory most directly causes the current ratio to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 1, "why": "Current assets decrease while current liabilities are unchanged.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "If beginning inventory is 50, purchases are 300, and ending inventory is 70, COGS is:", "choices": ["280", "320", "420"], "a": 0, "why": "COGS = beginning inventory + purchases − ending inventory = 280.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "Inventory of 200 under LIFO with a reserve of 40 implies FIFO inventory of:", "choices": ["160", "200", "240"], "a": 2, "why": "FIFO inventory ≈ 200 + 40 = 240.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "When input prices are falling, FIFO compared with LIFO most likely reports:", "choices": ["higher COGS", "lower COGS", "the same COGS by definition"], "a": 0, "why": "FIFO sends older, higher costs to COGS when prices are falling.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "A company changes from FIFO to weighted average. The analyst should primarily assess:", "choices": ["comparability across periods", "only cash dividends", "only share count"], "a": 0, "why": "Cost-flow changes can distort trend comparisons.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "High inventory turnover is always favorable:", "choices": ["true", "false, because it may indicate inadequate inventory", "true only under IFRS"], "a": 1, "why": "Very high turnover may reflect stockouts or insufficient inventory.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "Which ratio is most directly affected by a higher ending inventory?", "choices": ["Current ratio", "Debt-to-equity only", "Interest coverage only"], "a": 0, "why": "Inventory is a current asset.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "If COGS is 720 and average inventory is 120, inventory turnover is:", "choices": ["4.0", "6.0", "8.0"], "a": 1, "why": "720/120 = 6.0.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "An analyst comparing FIFO and LIFO firms should most likely adjust:", "choices": ["inventory and COGS", "only dividends", "only cash balances"], "a": 0, "why": "Both the balance sheet and income statement are affected.", "module": 5, "difficulty": "medium"}, {"topic": "fsa", "q": "Capitalizing a cost instead of expensing it immediately initially results in:", "choices": ["higher profit and assets", "lower profit and assets", "higher cash flow from operations in all frameworks without classification effects"], "a": 0, "why": "Capitalization defers expense and records an asset.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Straight-line depreciation is calculated using:", "choices": ["cost divided by age", "(cost − residual value)/useful life", "market value/useful life"], "a": 1, "why": "Depreciable cost excludes residual value.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "A longer estimated useful life, all else equal, produces:", "choices": ["higher annual depreciation", "lower annual depreciation", "no effect on carrying value"], "a": 1, "why": "The depreciable base is spread over more periods.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Accelerated depreciation compared with straight-line normally causes early-period profit to be:", "choices": ["higher", "lower", "identical"], "a": 1, "why": "Accelerated methods record more depreciation early.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Depreciation is best described as:", "choices": ["a valuation of current market value", "systematic allocation of depreciable cost", "a financing cash outflow"], "a": 1, "why": "Depreciation allocates cost; it does not determine market value.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "An impairment loss causes current-period assets and profit to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 1, "why": "The asset is written down and a loss is recognized.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "After an impairment, future depreciation may be:", "choices": ["lower because the carrying amount is lower", "higher by definition", "unchanged in every case"], "a": 0, "why": "The new depreciable base may be lower.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Under IFRS, upward revaluation of qualifying PPE is:", "choices": ["potentially permitted", "always prohibited", "required annually"], "a": 0, "why": "IFRS permits a revaluation model for classes of qualifying assets.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Under US GAAP, upward revaluation of operating PPE is generally:", "choices": ["permitted", "not permitted", "required"], "a": 1, "why": "US GAAP generally uses historical cost less depreciation and impairment.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Cash paid to acquire equipment is normally classified as:", "choices": ["operating", "investing", "financing"], "a": 1, "why": "Acquisition of long-term assets is investing cash flow.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "An increase in capitalized costs relative to expensed costs may initially improve:", "choices": ["profit margin", "cash collected from customers", "debt maturity"], "a": 0, "why": "Current expense is lower, increasing reported profit.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Equipment cost is 90, residual value 10, useful life four years. Annual straight-line depreciation is:", "choices": ["20", "22.5", "25"], "a": 0, "why": "(90−10)/4 = 20.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "A change in useful life is generally treated as:", "choices": ["a prospective change in estimate", "a retrospective error correction in every case", "a financing transaction"], "a": 0, "why": "Changes in estimates are generally applied prospectively.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Asset turnover is calculated as:", "choices": ["revenue/average total assets", "assets/revenue", "net income/assets"], "a": 0, "why": "Asset turnover measures revenue generated per unit of assets.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Capitalizing interest during construction most directly:", "choices": ["increases the asset's carrying amount", "reduces the asset to zero", "creates financing cash inflow"], "a": 0, "why": "Eligible borrowing cost becomes part of the asset cost.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "A company with older, largely depreciated assets may report asset turnover that is:", "choices": ["artificially high relative to a firm with newer assets", "always lower", "unaffected by asset age"], "a": 0, "why": "A lower net asset denominator can raise turnover.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "An asset disposal gain occurs when proceeds are:", "choices": ["greater than carrying amount", "less than original cost only", "equal to accumulated depreciation"], "a": 0, "why": "Gain equals proceeds minus carrying amount when positive.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Research expenditure is most commonly:", "choices": ["expensed as incurred", "always capitalized", "recorded as inventory"], "a": 0, "why": "Research costs are generally expensed; development treatment depends on the framework and criteria.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Compared with expensing, capitalization generally causes early operating cash flow to appear:", "choices": ["higher when the cash outflow is classified as investing", "lower in all cases", "unchanged under every classification"], "a": 0, "why": "Capitalized asset purchases are generally investing rather than operating cash flow.", "module": 6, "difficulty": "medium"}, {"topic": "fsa", "q": "Frequent impairments after acquisitions may suggest:", "choices": ["overly optimistic acquisition assumptions", "guaranteed superior returns", "no estimation uncertainty"], "a": 0, "why": "Repeated impairments can indicate overpayment or optimistic forecasts.", "module": 6, "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Trust in investment markets most directly helps to:", "choices": ["reduce participation and raise monitoring costs", "support participation and efficient capital allocation", "eliminate all investment losses"], "a": 1, "why": "Trust reduces information and monitoring frictions and supports market participation.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "An action can be legal but unethical because:", "choices": ["law always requires maximum ethical conduct", "legal rules may set only minimum requirements", "ethics applies only outside employment"], "a": 1, "why": "Ethical duties may exceed minimum legal requirements.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Aggressive bonus targets are best classified as:", "choices": ["a situational influence on judgment", "proof of misconduct", "a market index"], "a": 0, "why": "Incentives can pressure judgment even before a violation occurs.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "The first step in a structured ethical decision process is most likely to:", "choices": ["identify relevant facts", "choose the most profitable action", "contact the media"], "a": 0, "why": "Reliable decisions begin with the facts and context.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Professionalism combines specialized competence with:", "choices": ["duties to clients and society", "guaranteed returns", "freedom from regulation"], "a": 0, "why": "Professional status carries obligations beyond technical skill.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "A team norm of hiding small errors is:", "choices": ["a valid defense", "a situational influence, not a justification", "required by confidentiality"], "a": 1, "why": "Group behavior can normalize misconduct but does not excuse it.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Ethical fading occurs when a person:", "choices": ["fails to recognize the ethical dimension of a decision", "calculates NPV incorrectly", "discloses a conflict"], "a": 0, "why": "Pressure and framing can cause the ethical issue to disappear from attention.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Which response best protects long-term trust?", "choices": ["conceal a minor error", "correct and transparently communicate a material error", "wait for a complaint"], "a": 1, "why": "Correction and transparency protect clients and credibility.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Good intentions without adequate competence are:", "choices": ["sufficient", "insufficient for professional conduct", "required by law to be rewarded"], "a": 1, "why": "Professionals need both integrity and competence.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "A decision framework should consider:", "choices": ["only immediate profit", "stakeholders and long-term consequences", "only supervisor preference"], "a": 1, "why": "Ethical analysis considers affected parties and broader consequences.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Authority pressure most directly creates risk that an employee will:", "choices": ["suspend independent judgment", "increase diversification", "reduce materiality"], "a": 0, "why": "People may comply with authority despite contrary duties.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Trust is best viewed as:", "choices": ["irrelevant to market efficiency", "an economic asset that lowers frictions", "a substitute for controls"], "a": 1, "why": "Trust supports transactions but does not replace controls.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "When a rule is silent, a professional should:", "choices": ["exploit the gap", "apply ethical principles and professional judgment", "assume every action is permitted"], "a": 1, "why": "Ethics guides conduct where law or rules are incomplete.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Which is most likely an affected stakeholder in a misleading research report?", "choices": ["clients only", "clients, employer, issuer, and market participants", "the analyst only"], "a": 1, "why": "Misleading work can affect many parties.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Documenting an ethical decision primarily improves:", "choices": ["defensibility and accountability", "investment return guarantees", "legal immunity"], "a": 0, "why": "Documentation shows the facts, reasoning, and actions taken.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "A professional should evaluate incentives:", "choices": ["only after misconduct", "before acting because they may bias judgment", "never"], "a": 1, "why": "Recognizing pressure early helps prevent biased conduct.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "A supervisor says, 'Everyone uses these optimistic assumptions.' The best response is to:", "choices": ["accept the group norm", "independently test whether the assumptions have a reasonable basis", "remove all assumptions"], "a": 1, "why": "Common practice does not establish quality or ethics.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Ethical conduct most directly supports the profession by:", "choices": ["protecting credibility and public confidence", "eliminating market volatility", "ensuring every forecast is accurate"], "a": 0, "why": "Integrity and competence sustain confidence despite unavoidable uncertainty.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "The strongest ethical alternative is generally one that:", "choices": ["maximizes personal gain", "meets duties and minimizes harm to stakeholders", "is least documented"], "a": 1, "why": "Professional duties and stakeholder consequences guide the decision.", "difficulty": "medium"}, {"topic": "ethics", "module": 1, "q": "Reflection after a decision is useful because it:", "choices": ["improves future judgment and controls", "changes historical facts", "removes all conflicts"], "a": 0, "why": "Review helps identify lessons and process improvements.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "The Code of Ethics primarily states:", "choices": ["broad professional principles", "detailed accounting rules", "exam scheduling requirements"], "a": 0, "why": "The Code provides overarching principles.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "The Standards of Professional Conduct are organized into:", "choices": ["seven major Standards", "three accounting statements", "ten economic sectors"], "a": 0, "why": "The Standards are grouped into seven areas.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "When local law is less strict than the Standards, the member should generally follow:", "choices": ["local law only", "the stricter Standards", "employer preference"], "a": 1, "why": "Use the stricter applicable requirement unless prohibited by law.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "A person who knowingly assists a violation may:", "choices": ["avoid responsibility because another person initiated it", "also violate the Standards", "automatically satisfy professionalism"], "a": 1, "why": "Knowing participation is prohibited.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "Dissociation is most appropriate when:", "choices": ["a violation continues and cannot be corrected", "a client asks a question", "returns are negative"], "a": 0, "why": "A member should not remain associated with ongoing misconduct.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "Disclosure of a conflict:", "choices": ["cures false research", "helps clients evaluate the conflict but does not excuse bias", "is never necessary"], "a": 1, "why": "Disclosure is important but cannot make dishonest conduct acceptable.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "Material nonpublic information belongs primarily under:", "choices": ["Integrity of Capital Markets", "Duties to Employers", "Responsibilities as a Candidate only"], "a": 0, "why": "Standard II covers material nonpublic information and manipulation.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "Suitability belongs primarily under:", "choices": ["Duties to Clients", "Professionalism only", "Duties to Employers"], "a": 0, "why": "Suitability is a client duty.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "Reasonable basis belongs primarily under:", "choices": ["Investment Analysis, Recommendations, and Actions", "Capital Markets only", "Employer loyalty"], "a": 0, "why": "Standard V requires diligence and a reasonable basis.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "Referral fees belong primarily under:", "choices": ["Conflicts of Interest", "Market manipulation", "Knowledge of law only"], "a": 0, "why": "Referral arrangements require disclosure under conflicts.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "Exam misconduct is covered primarily by:", "choices": ["Responsibilities as a CFA Institute Member or Candidate", "Duties to Clients", "Corporate governance"], "a": 0, "why": "Standard VII addresses program and designation integrity.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "A written restricted-list policy is primarily a:", "choices": ["preventive control", "guarantee of compliance", "substitute for training"], "a": 0, "why": "It helps prevent inappropriate trading or recommendations.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "A scenario can violate multiple Standards:", "choices": ["true", "false", "only with criminal conduct"], "a": 0, "why": "Professional duties often overlap.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "The most appropriate first response to suspected misconduct is always public disclosure:", "choices": ["true", "false; facts and internal escalation may be appropriate first", "true if compensation is involved"], "a": 1, "why": "The response depends on facts, law, duties, and available channels.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "The duty to maintain competence appears in:", "choices": ["the Code of Ethics", "only employment contracts", "only securities law"], "a": 0, "why": "The Code calls for competence and professional improvement.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "A member is instructed to issue unsupported research. The member should most likely:", "choices": ["comply because of employer loyalty", "refuse and escalate", "remove all disclosures"], "a": 1, "why": "Employer loyalty does not require participation in a violation.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "Client interests should be placed:", "choices": ["above personal interests in professional activities", "below bonus targets", "below issuer interests"], "a": 0, "why": "The Code emphasizes client interests and integrity.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "Which action best supports compliance?", "choices": ["keeping no records", "documenting approvals and research support", "using oral policies only"], "a": 1, "why": "Documentation supports supervision, review, and accountability.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "The stricter-rule principle applies when:", "choices": ["requirements differ", "returns differ", "currencies differ"], "a": 0, "why": "Conflicts between applicable standards require determining the stricter rule.", "difficulty": "medium"}, {"topic": "ethics", "module": 2, "q": "Independence and objectivity belong primarily under:", "choices": ["Professionalism", "Duties to Employers", "Portfolio Construction"], "a": 0, "why": "They are addressed under Standard I.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "The future value of 1,000 invested for two years at 10% is:", "choices": ["1,100", "1,200", "1,210"], "a": 2, "why": "1,000(1.10)^2 = 1,210.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "The present value of 1,210 received in two years at 10% is:", "choices": ["1,000", "1,100", "1,210"], "a": 0, "why": "1,210/(1.10)^2 = 1,000.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "All else equal, a higher discount rate causes present value to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 1, "why": "Future cash flows are discounted more heavily.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "An ordinary annuity makes payments at the:", "choices": ["beginning of each period", "end of each period", "middle of each period"], "a": 1, "why": "Ordinary-annuity payments occur at period end.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "An annuity due makes payments at the:", "choices": ["beginning of each period", "end of each period", "final date only"], "a": 0, "why": "Annuity-due payments occur one period earlier.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "Compared with an ordinary annuity, an otherwise identical annuity due has a present value that is:", "choices": ["lower", "higher", "equal"], "a": 1, "why": "Every payment is received one period earlier.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "The present value of a level perpetuity paying 200 with r=4% is:", "choices": ["5,000", "800", "208"], "a": 0, "why": "200/0.04 = 5,000.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "A growing perpetuity formula requires:", "choices": ["g > r", "r > g", "r = g"], "a": 1, "why": "The discount rate must exceed growth.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "In V0=C1/(r−g), C1 is:", "choices": ["the cash flow just paid", "the next-period cash flow", "the terminal value"], "a": 1, "why": "The numerator is the payment one period from now.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "A positive NPV indicates that a project:", "choices": ["is expected to add value at the required return", "has no risk", "has a negative IRR"], "a": 0, "why": "Benefits exceed costs in present-value terms.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "On a financial calculator, PV and FV generally require:", "choices": ["the same sign", "opposite signs", "no signs"], "a": 1, "why": "Cash paid and cash received have opposite signs.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "Before a new BA II Plus TVM problem, the user should:", "choices": ["clear TVM registers", "leave prior values", "set all values to one manually"], "a": 0, "why": "Old register values can contaminate the calculation.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "Monthly cash flows with a nominal annual rate require:", "choices": ["consistent monthly rate and monthly periods", "annual periods only", "no frequency conversion"], "a": 0, "why": "Rate and period units must match.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "The future value of 500 at 8% for one year is:", "choices": ["540", "508", "625"], "a": 0, "why": "500×1.08 = 540.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "The present value of 540 one year from now at 8% is:", "choices": ["500", "540", "583.2"], "a": 0, "why": "540/1.08 = 500.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "If compounding frequency increases while the quoted nominal rate is unchanged, effective annual yield generally:", "choices": ["increases", "decreases to zero", "remains identical"], "a": 0, "why": "More frequent compounding raises the effective annual yield.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "A project costs 100 and returns 110 in one year. At a 10% required return, NPV is:", "choices": ["0", "10", "−10"], "a": 0, "why": "PV of 110 is 100, so NPV is zero.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "The value today of cash flows occurring at different dates should be found by:", "choices": ["adding nominal amounts without adjustment", "discounting each to a common date", "using only the largest flow"], "a": 1, "why": "Cash flows must be expressed at the same valuation date.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "If the first perpetuity payment occurs immediately, C/r gives the value:", "choices": ["one period before the first payment", "at the same instant as the first payment without adjustment", "only after ten periods"], "a": 0, "why": "The standard formula values the stream one period before its first payment.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "An annuity-due value can be obtained from an ordinary-annuity value by multiplying by:", "choices": ["1+r", "1−r", "n"], "a": 0, "why": "Each payment is shifted one period earlier.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "If r increases while C and g remain constant, growing-perpetuity value:", "choices": ["increases", "decreases", "becomes independent of r"], "a": 1, "why": "The denominator r−g increases.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "If g approaches r from below, growing-perpetuity value:", "choices": ["falls toward zero", "rises sharply", "remains fixed"], "a": 1, "why": "The denominator becomes very small.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "Uneven cash flows on a BA II Plus are most directly entered using the:", "choices": ["CF worksheet", "bond coupon key only", "statistics worksheet only"], "a": 0, "why": "The cash-flow worksheet handles irregular cash flows.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "Rounding each present value too early can:", "choices": ["create cumulative error", "improve precision", "make signs irrelevant"], "a": 0, "why": "Keep sufficient precision until the final answer.", "difficulty": "medium"}, {"topic": "quant", "module": 3, "q": "The most reliable first step in a TVM question is to:", "choices": ["draw a timeline", "guess the formula", "enter random calculator values"], "a": 0, "why": "A timeline clarifies dates, signs, and cash-flow pattern.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "A change in the price of the good itself causes:", "choices": ["a demand-curve shift", "movement along the demand curve", "a supply-curve shift"], "a": 1, "why": "Own-price changes cause movement along a curve.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "Income rises for a normal good. Demand most likely:", "choices": ["shifts left", "shifts right", "does not change"], "a": 1, "why": "Normal-good demand rises with income.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "The price of a substitute rises. Demand for the original good most likely:", "choices": ["rises", "falls", "remains unchanged"], "a": 0, "why": "Consumers switch toward the relatively cheaper original good.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "The price of a complement rises. Demand for the original good most likely:", "choices": ["rises", "falls", "becomes perfectly elastic"], "a": 1, "why": "Complementary goods are consumed together.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "Higher input costs most likely shift supply:", "choices": ["right", "left", "not at all"], "a": 1, "why": "Higher production cost reduces supply at each price.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "A technological improvement most likely shifts supply:", "choices": ["right", "left", "vertically"], "a": 0, "why": "Technology lowers cost or increases productivity.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "A price below equilibrium creates:", "choices": ["surplus", "shortage", "market clearing"], "a": 1, "why": "Quantity demanded exceeds quantity supplied.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "A price above equilibrium creates:", "choices": ["shortage", "surplus", "no pressure on price"], "a": 1, "why": "Quantity supplied exceeds quantity demanded.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "A binding price ceiling is set:", "choices": ["above equilibrium", "below equilibrium", "at any price"], "a": 1, "why": "Only a ceiling below equilibrium constrains price.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "A binding price floor most likely creates:", "choices": ["shortage", "surplus", "lower supply"], "a": 1, "why": "The controlled price is above equilibrium.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "Elastic demand has absolute elasticity:", "choices": ["less than 1", "greater than 1", "equal to zero"], "a": 1, "why": "Quantity responds proportionally more than price.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "When demand is inelastic, a price increase most likely causes total revenue to:", "choices": ["rise", "fall", "become zero"], "a": 0, "why": "The quantity reduction is proportionally smaller.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "Unit-elastic demand implies total revenue is approximately:", "choices": ["unchanged after a small price change", "always rising", "always falling"], "a": 0, "why": "Price and quantity effects offset.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "The side of a taxed market bearing more burden is usually the side that is:", "choices": ["more elastic", "less elastic", "legally named"], "a": 1, "why": "The less elastic side has fewer alternatives.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "If both demand and supply increase, equilibrium quantity:", "choices": ["must rise", "must fall", "is indeterminate"], "a": 0, "why": "Both shifts raise quantity.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "If demand increases and supply decreases, equilibrium price:", "choices": ["must rise", "must fall", "is indeterminate"], "a": 0, "why": "Both shifts raise price.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "If demand decreases and supply increases, equilibrium price:", "choices": ["must rise", "must fall", "is indeterminate"], "a": 1, "why": "Both shifts lower price.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "A nonbinding price ceiling:", "choices": ["creates shortage", "has no market effect", "creates surplus"], "a": 1, "why": "A ceiling above equilibrium does not constrain price.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "Consumer surplus is the difference between:", "choices": ["willingness to pay and price paid", "price received and minimum acceptable price", "revenue and cost"], "a": 0, "why": "It measures buyer benefit.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "Producer surplus is the difference between:", "choices": ["willingness to pay and price", "price received and minimum acceptable price", "profit and tax only"], "a": 1, "why": "It measures seller benefit above reservation price.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "A tax generally causes total surplus to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 1, "why": "Taxes reduce mutually beneficial trades and create deadweight loss.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "Demand is Qd=80−P and supply Qs=20+P. Equilibrium price is:", "choices": ["20", "30", "50"], "a": 1, "why": "80−P=20+P gives P=30.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "Using the same equations, equilibrium quantity is:", "choices": ["30", "50", "60"], "a": 1, "why": "Q=80−30=50.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "Price rises 4% and quantity demanded falls 2%. Demand is:", "choices": ["elastic", "inelastic", "unit elastic"], "a": 1, "why": "Elasticity magnitude is 0.5.", "difficulty": "medium"}, {"topic": "economics", "module": 0, "q": "A subsidy to producers most likely shifts supply:", "choices": ["left", "right", "not at all"], "a": 1, "why": "A subsidy lowers effective production cost.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "A budget constraint shows:", "choices": ["all preferred bundles", "all affordable bundles", "all market-equilibrium bundles"], "a": 1, "why": "It reflects income and prices.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "If income rises with prices unchanged, the budget line:", "choices": ["shifts outward in parallel", "rotates inward", "does not move"], "a": 0, "why": "Both intercepts increase proportionally.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "If the price of X falls, the budget line:", "choices": ["rotates outward along the X-axis", "shifts parallel inward", "rotates inward along the Y-axis"], "a": 0, "why": "The X-intercept increases.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "At an interior optimum:", "choices": ["MRS equals the price ratio", "income equals zero", "marginal utilities must be equal"], "a": 0, "why": "Relative willingness to substitute equals relative market price.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "If MUx/Px exceeds MUy/Py, the consumer should buy:", "choices": ["more X and less Y", "less X and more Y", "neither good"], "a": 0, "why": "X provides more utility per currency unit.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "Indifference curves generally slope downward because:", "choices": ["both goods are bad", "maintaining utility requires compensation", "income is fixed"], "a": 1, "why": "Less of one good requires more of the other.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "Convex indifference curves reflect:", "choices": ["increasing MRS", "diminishing MRS", "constant income"], "a": 1, "why": "Consumers generally prefer balanced bundles.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "The substitution effect of a fall in X's price causes demand for X to:", "choices": ["rise", "fall", "remain unchanged"], "a": 0, "why": "X becomes relatively cheaper.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "For a normal good, the income effect of a price decline causes quantity demanded to:", "choices": ["rise", "fall", "become zero"], "a": 0, "why": "Higher real purchasing power increases normal-good demand.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "For an inferior good, an income increase causes demand to:", "choices": ["rise", "fall", "become perfectly inelastic"], "a": 1, "why": "Inferior-good demand falls with income.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "A Giffen good is:", "choices": ["normal", "inferior with income effect dominating substitution effect", "a complement"], "a": 1, "why": "Its demand can rise with price in rare cases.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "Market demand is formed by:", "choices": ["vertically summing prices", "horizontally summing quantities", "averaging incomes only"], "a": 1, "why": "Quantities demanded are added at each price.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "Income 100, Px 5. Maximum X is:", "choices": ["5", "20", "100"], "a": 1, "why": "100/5=20.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "Income 100, Py 10. Maximum Y is:", "choices": ["10", "20", "100"], "a": 0, "why": "100/10=10.", "difficulty": "medium"}, {"topic": "economics", "module": 1, "q": "A corner solution occurs when:", "choices": ["the optimum contains only one good", "MRS always equals 1", "income is unlimited"], "a": 0, "why": "Tangency need not occur.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Inflation is best described as:", "choices": ["a sustained rise in the general price level", "a rise in one commodity price", "a fall in real GDP only"], "a": 0, "why": "Inflation concerns the broad price level.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Unexpected inflation most likely benefits:", "choices": ["fixed-rate lenders", "fixed-rate borrowers", "cash holders"], "a": 1, "why": "Borrowers repay with less valuable money.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Unexpected inflation most likely harms:", "choices": ["fixed-rate lenders", "fixed-rate borrowers", "owners of real assets in every case"], "a": 0, "why": "Real repayment value falls.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Approximate real return equals:", "choices": ["nominal plus inflation", "nominal minus inflation", "inflation minus nominal"], "a": 1, "why": "This is the common approximation.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Nominal return 9%, inflation 4%. Approximate real return:", "choices": ["5%", "13%", "2.25%"], "a": 0, "why": "9−4=5.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Exact real return uses:", "choices": ["1+nominal divided by 1+inflation, minus 1", "nominal multiplied by inflation", "nominal divided by inflation"], "a": 0, "why": "This is the exact Fisher adjustment.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Core inflation generally excludes:", "choices": ["selected volatile items", "all services", "all wages"], "a": 0, "why": "It aims to reveal the underlying trend.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "CPI most directly tracks:", "choices": ["a consumer basket", "only producer inputs", "only imported goods"], "a": 0, "why": "CPI measures household consumer prices.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "A GDP deflator covers:", "choices": ["domestically produced final output", "only a fixed consumer basket", "only exports"], "a": 0, "why": "Its coverage differs from CPI.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Expected inflation tends to be incorporated into:", "choices": ["nominal interest rates", "historical cost only", "real output only"], "a": 0, "why": "Lenders demand inflation compensation.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "If expected inflation rises and real rates are unchanged, nominal rates generally:", "choices": ["rise", "fall", "remain fixed"], "a": 0, "why": "Fisher logic implies a higher nominal rate.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "A one-time increase in oil price is not necessarily:", "choices": ["relative-price change", "general inflation", "a supply shock"], "a": 1, "why": "Inflation requires broader sustained price growth.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "CPI substitution bias tends to:", "choices": ["overstate cost-of-living increases", "understate every price", "eliminate quality change"], "a": 0, "why": "Fixed baskets may not reflect substitution toward cheaper goods.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Quality improvements can cause measured inflation to:", "choices": ["be overstated if not fully adjusted", "always be understated", "equal zero"], "a": 0, "why": "Part of a price rise may pay for improved quality.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Nominal rate 8%, expected inflation 3%. Approximate real rate:", "choices": ["5%", "11%", "2.67%"], "a": 0, "why": "8−3=5.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Under exact Fisher, real rate is lower than the simple approximation when rates are positive because of:", "choices": ["the interaction term", "tax only", "duration"], "a": 0, "why": "Compounding creates the cross-product.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Deflation is:", "choices": ["a sustained fall in the general price level", "slower positive inflation only", "a fall in one price"], "a": 0, "why": "Deflation is negative general inflation.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Disinflation is:", "choices": ["a lower positive inflation rate", "deflation in all cases", "higher expected inflation"], "a": 0, "why": "Prices still rise, but more slowly.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "A real return is most relevant for measuring:", "choices": ["purchasing-power growth", "nominal account balance only", "coupon frequency"], "a": 0, "why": "It adjusts for inflation.", "difficulty": "medium"}, {"topic": "economics", "module": 4, "q": "Inflation uncertainty generally causes lenders to demand:", "choices": ["a higher risk premium", "a lower nominal rate", "no compensation"], "a": 0, "why": "Uncertainty increases required compensation.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "The preferred value-maximizing capital-budgeting criterion is:", "choices": ["NPV", "payback", "accounting return"], "a": 0, "why": "NPV measures expected value added.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "An independent project should be accepted when:", "choices": ["NPV > 0", "IRR < required return", "payback is longest"], "a": 0, "why": "Positive NPV indicates return above the requirement.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "A sunk cost should be:", "choices": ["included", "excluded", "discounted at the risk-free rate"], "a": 1, "why": "It has already occurred.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "An opportunity cost should be:", "choices": ["included", "excluded", "treated as financing"], "a": 0, "why": "It is a forgone benefit caused by the project.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Project cash flows should generally be:", "choices": ["incremental and after tax", "accounting earnings before tax", "total company revenue"], "a": 0, "why": "Only incremental after-tax cash effects are relevant.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Interest expense is usually excluded from project cash flow because:", "choices": ["financing cost is reflected in the discount rate", "interest is never paid", "taxes do not matter"], "a": 0, "why": "Including it would double-count financing.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "NPV equals:", "choices": ["PV inflows minus PV outflows", "undiscounted inflows minus cost", "IRR minus WACC"], "a": 0, "why": "NPV is a present-value measure.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "IRR is the rate that makes:", "choices": ["NPV zero", "payback zero", "revenue zero"], "a": 0, "why": "IRR solves NPV=0.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "For a conventional independent project, accept when:", "choices": ["IRR > required return", "IRR < required return", "IRR = 0 only"], "a": 0, "why": "IRR above the hurdle indicates sufficient return.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Multiple IRRs can occur when:", "choices": ["cash-flow signs change more than once", "all cash flows are positive after the outlay", "NPV is positive"], "a": 0, "why": "Nonconventional cash flows can create multiple roots.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "For mutually exclusive projects with ranking conflict, choose based on:", "choices": ["higher NPV", "higher IRR always", "shorter payback"], "a": 0, "why": "NPV maximizes absolute value.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Payback ignores:", "choices": ["time value and post-cutoff cash flows", "initial investment", "all cash flows before cutoff"], "a": 0, "why": "These are its main weaknesses.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Discounted payback corrects for:", "choices": ["time value of money", "post-cutoff cash flows", "multiple IRRs"], "a": 0, "why": "It discounts cash flows but still ignores later ones.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "PI greater than 1 corresponds to:", "choices": ["positive NPV", "negative NPV", "zero initial investment"], "a": 0, "why": "PV benefits exceed cost.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "PI is particularly useful under:", "choices": ["capital rationing", "unlimited capital with mutually exclusive projects only", "zero discount rates"], "a": 0, "why": "It ranks value per currency invested.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Working-capital investment at project start is generally:", "choices": ["an initial outflow", "an operating inflow", "irrelevant"], "a": 0, "why": "Cash is tied up in operations.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Recovery of working capital at project end is generally:", "choices": ["a terminal inflow", "a sunk cost", "depreciation"], "a": 0, "why": "The invested working capital is released.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Depreciation matters to cash flow primarily through:", "choices": ["its tax shield", "its direct cash payment", "its effect on revenue only"], "a": 0, "why": "Depreciation reduces taxable income.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Cannibalization is:", "choices": ["a negative externality on existing products", "a sunk cost", "financing cash flow"], "a": 0, "why": "Lost existing sales are incremental to the project decision.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "A positive side effect on another product should be:", "choices": ["included", "excluded", "treated as interest"], "a": 0, "why": "It is incremental.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Feasibility-study spending already incurred is:", "choices": ["sunk", "opportunity cost", "terminal cash flow"], "a": 0, "why": "It cannot be changed by the decision.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Land owned by the firm but usable elsewhere has:", "choices": ["an opportunity cost", "no project cost", "only book value relevance"], "a": 0, "why": "The best alternative use is forgone.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "A project costs 100 and has PV inflows 125. NPV:", "choices": ["25", "125", "−25"], "a": 0, "why": "125−100=25.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "The same project has PI:", "choices": ["1.25", "0.80", "25"], "a": 0, "why": "125/100=1.25.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "A project costs 200 and pays 100 in year 1 and 120 in year 2. At 10%, NPV is closest to:", "choices": ["−10.74", "8.26", "20.00"], "a": 1, "why": "100/1.1 +120/1.21 −200 ≈ 8.26.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "A project with NPV zero is expected to earn:", "choices": ["exactly the required return", "zero accounting profit", "less than the required return"], "a": 0, "why": "The discounted value exactly equals cost.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "If the discount rate rises, NPV for a conventional project generally:", "choices": ["falls", "rises", "is unchanged"], "a": 0, "why": "Future cash flows are discounted more heavily.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "If project risk exceeds firm average, the discount rate should generally be:", "choices": ["higher than firm WACC", "lower than firm WACC", "equal to risk-free rate"], "a": 0, "why": "The rate must match project risk.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Using company WACC for every project can cause:", "choices": ["acceptance of overly risky projects and rejection of safer ones", "perfect decisions", "no bias"], "a": 0, "why": "A single hurdle misprices project-specific risk.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Capital budgeting should use:", "choices": ["cash flows, not accounting profit", "net income only", "EBIT only"], "a": 0, "why": "Value depends on cash flows.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "Terminal salvage value should be included:", "choices": ["after tax", "before tax only", "never"], "a": 0, "why": "Tax effects on disposal are incremental.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "If sale price exceeds tax book value, disposal may create:", "choices": ["tax on the gain", "a tax deduction only", "no tax effect"], "a": 0, "why": "The gain may be taxable.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "A project with conventional cash flows has NPV positive at 8%. Its IRR is most likely:", "choices": ["above 8%", "below 8%", "equal to zero"], "a": 0, "why": "A positive NPV at 8% implies the zero-NPV rate is higher.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "When capital is not rationed, PI should not replace NPV for:", "choices": ["mutually exclusive projects", "independent projects", "screening positive NPV"], "a": 0, "why": "PI can misrank projects of different scale.", "difficulty": "medium"}, {"topic": "corporate", "module": 1, "q": "The NPV profile plots NPV against:", "choices": ["discount rate", "project age only", "accounting profit"], "a": 0, "why": "It shows sensitivity to required return.", "difficulty": "medium"}], "formulas": [["Geometric return", "[(Ending value / Beginning value)^(1/n)] − 1"], ["Present value", "PV = FV / (1 + r)^n"], ["Growing perpetuity", "PV = C1 / (r − g), where r > g"], ["Portfolio expected return", "E(Rp) = Σ wiE(Ri)"], ["Two-asset variance", "w1²σ1² + w2²σ2² + 2w1w2Cov12"], ["CAPM", "E(Ri) = Rf + βi[E(Rm) − Rf]"], ["WACC", "wd rd(1−t) + wp rp + we re"], ["Gordon growth", "V0 = D1 / (r − g)"], ["Long forward payoff", "ST − K"], ["European put–call parity", "c + PV(X) = p + S0 (non-dividend-paying asset)"]], "guides": {"quant": {"overview": "Quantitative Methods supplies the mathematical language used throughout Level I. Focus first on cash-flow timing, return measurement, probability, sampling, estimation, hypothesis testing, regression, simulation, and interpreting model output. Do not merely memorize equations: identify what each variable means, the assumptions behind the method, and how a change in an input affects the result.", "workflow": ["Draw a cash-flow timeline before using a formula or calculator.", "Write the units: annual, monthly, percentage, decimal, population, or sample.", "Estimate the direction and approximate size before calculating.", "Check whether the question asks for a population parameter, sample statistic, test decision, or forecast."], "formulas": [["Compound value", "FV = PV(1+r)^n"], ["Present value", "PV = FV/(1+r)^n"], ["Geometric mean", "[(1+R1)…(1+Rn)]^(1/n) − 1"], ["Standard error of mean", "s/√n"], ["Test statistic", "(estimate − hypothesized value)/standard error"], ["Simple regression", "Yi = b0 + b1Xi + εi"]], "traps": ["Using an arithmetic mean for a compounded multi-period growth rate.", "Mixing annual and periodic rates.", "Interpreting failure to reject as proof that the null is true.", "Treating correlation as causation.", "Ignoring assumptions or sample-selection bias."]}, "economics": {"overview": "Economics questions test how households, firms, governments, central banks, and currency markets respond to incentives and constraints. Build a clear cause-and-effect chain: what shifts, which curve moves, how equilibrium changes, and whether the result is nominal or real. For macroeconomics, connect growth, inflation, unemployment, policy, interest rates, and exchange rates.", "workflow": ["Identify the market and the variable held constant.", "Separate a curve shift from movement along a curve.", "State the initial equilibrium and the direction of the shock.", "For policy questions, distinguish objective, instrument, transmission mechanism, and possible limitation."], "formulas": [["Price elasticity of demand", "%Δ quantity demanded / %Δ price"], ["GDP expenditure approach", "C + I + G + (X−M)"], ["Real interest rate approximation", "Nominal rate − expected inflation"], ["Forward FX relation concept", "Forward premium/discount reflects interest-rate differential under covered parity"]], "traps": ["Confusing changes in demand with changes in quantity demanded.", "Assuming a policy works instantly or without expectations.", "Mixing nominal GDP growth with real output growth.", "Reversing base and price currencies in FX quotes."]}, "corporate": {"overview": "Corporate Finance links governance, investment decisions, financing decisions, liquidity, and value creation. The central principle is incremental after-tax cash flow discounted at a rate appropriate for its risk. Learn why NPV is the preferred decision rule, how financing mix affects the cost of capital, and how working-capital choices affect liquidity and profitability.", "workflow": ["Use incremental cash flows only.", "Include opportunity costs and side effects; exclude sunk costs.", "Match project risk with the discount rate.", "Check whether a ratio change improves liquidity at the expense of profitability or vice versa."], "formulas": [["NPV", "Σ CFt/(1+r)^t − initial investment"], ["WACC", "wd rd(1−T) + wp rp + we re"], ["Cash conversion cycle", "Inventory days + Receivable days − Payable days"], ["Degree of operating leverage", "%Δ operating profit / %Δ sales"]], "traps": ["Using accounting profit instead of cash flow.", "Discounting all projects at the company WACC regardless of risk.", "Including sunk costs.", "Assuming more debt always lowers WACC.", "Treating a shorter cash cycle as automatically good without considering operations."]}, "fsa": {"overview": "Financial Statement Analysis is a high-weight area. Learn how transactions flow through the income statement, balance sheet, cash-flow statement, and equity. Then analyze how accounting choices affect reported performance, cash flow, ratios, comparability, and earnings quality. Always distinguish an economic event from its accounting presentation.", "workflow": ["Identify the transaction and affected accounts.", "Trace its effect on profit, assets, liabilities, equity, and cash flow.", "Determine whether the difference is timing, classification, measurement, or disclosure.", "Recalculate ratios and explain the economic interpretation."], "formulas": [["Basic EPS", "(Net income − preferred dividends)/weighted-average common shares"], ["Current ratio", "Current assets/current liabilities"], ["Inventory turnover", "COGS/average inventory"], ["ROE", "Net income/average equity"], ["CFO indirect starting point", "Net income + noncash charges − operating asset increases + operating liability increases"]], "traps": ["Equating net income with cash generated.", "Ignoring average balance-sheet values in turnover ratios.", "Assuming an unmodified audit opinion guarantees financial health.", "Comparing ratios without adjusting for accounting policy differences.", "Confusing temporary and permanent tax differences."]}, "equity": {"overview": "Equity Investments combines market structure, indexes, efficiency, industry and company analysis, forecasting, and valuation. A valuation conclusion is only as sound as its assumptions. Separate the operating forecast from the discount rate, and connect competitive position, growth, margins, reinvestment, risk, and terminal value.", "workflow": ["Define the business and source of cash flows.", "Analyze industry structure and competitive advantage.", "Forecast revenue, margins, investment, and financing consistently.", "Select a valuation method appropriate to the company and available data.", "Stress-test growth, margins, and required return."], "formulas": [["Gordon growth model", "V0 = D1/(r−g), r>g"], ["Holding-period return", "(P1−P0+D1)/P0"], ["Market-cap index weight", "Company market cap/total index market cap"], ["Justified leading P/E concept", "Payout ratio/(r−g)"]], "traps": ["Using an unsustainable growth rate in a perpetual model.", "Treating a low P/E as proof of undervaluation.", "Ignoring dilution or capital needs.", "Confusing enterprise value with equity value.", "Using scenario probabilities that do not sum to 100%."]}, "fixed": {"overview": "Fixed Income questions require disciplined cash-flow valuation. Start with bond features and promised cash flows, then discount them using the appropriate curve. Understand yield measures, term structure, duration, convexity, embedded options, credit risk, and securitization. Always ask who owns the option and how a change in rates affects expected cash flows.", "workflow": ["Map every contractual cash flow.", "Identify whether the bond has an embedded option.", "Choose the correct yield or spot rates.", "Estimate direction using price–yield logic, then calculate.", "Separate interest-rate risk, reinvestment risk, liquidity risk, and credit risk."], "formulas": [["Bond price", "Σ CFt/(1+rt)^t"], ["Current yield", "Annual coupon/current price"], ["Approximate duration effect", "%ΔP ≈ −Modified duration × Δy"], ["Expected credit loss", "Probability of default × loss given default × exposure"]], "traps": ["Using coupon rate as the discount rate.", "Forgetting that price and yield move inversely.", "Applying plain duration to a bond whose cash flows change materially with rates.", "Confusing spread widening with falling required return.", "Assuming securitization removes the pool's risk."]}, "derivatives": {"overview": "Derivatives transfer or reshape risk. Master the payoff at expiration before studying value before expiration. Distinguish forwards, futures, swaps, calls, and puts; identify the long and short sides; and use no-arbitrage and replication. Options are asymmetric: the buyer has a right, while the writer has an obligation.", "workflow": ["Draw the payoff at expiration.", "Identify long versus short and right versus obligation.", "Separate payoff from profit by considering the initial premium.", "Use replication or put–call parity to check prices.", "State the effect of underlying price, volatility, time, rates, and income."], "formulas": [["Long forward payoff", "ST−K"], ["Long call payoff", "max(0, ST−X)"], ["Long put payoff", "max(0, X−ST)"], ["European put–call parity", "c + PV(X) = p + S0 for a non-dividend-paying asset"]], "traps": ["Calling an option payoff a profit without subtracting premium.", "Treating a forward as having limited downside.", "Confusing futures daily settlement with final payoff.", "Reversing put–call parity terms.", "Assuming option value can be negative to its holder."]}, "alternatives": {"overview": "Alternative Investments include private capital, real estate, infrastructure, commodities, hedge funds, and digital assets. Questions emphasize distinctive cash flows, leverage, illiquidity, valuation uncertainty, fees, governance, and data biases. Reported volatility may understate economic risk when prices are infrequent or model-based.", "workflow": ["Identify the return source and underlying economic exposure.", "Assess leverage, liquidity, valuation method, and fee structure.", "Check index and performance-reporting biases.", "Distinguish direct ownership from fund or derivative exposure.", "Review operational, legal, custody, and counterparty risks."], "formulas": [["Simple income capitalization", "Property value = NOI/capitalization rate"], ["Commodity futures total-return components", "Spot return + roll yield + collateral yield"], ["Private investment multiple", "Distributions and residual value / paid-in capital (concept varies by metric)"]], "traps": ["Comparing smoothed appraisal returns directly with traded-asset volatility.", "Ignoring carried interest and management fees.", "Treating every hedge-fund strategy as market neutral.", "Assuming illiquidity means low risk.", "Ignoring custody and operational risks for digital assets."]}, "portfolio": {"overview": "Portfolio Construction integrates risk, return, diversification, investor objectives, constraints, asset allocation, and risk management. The key insight is that portfolio risk depends on covariance, not only the risk of each asset. A suitable portfolio must reflect both willingness and ability to take risk, with the lower normally limiting.", "workflow": ["Define measurable return and risk objectives.", "List liquidity, horizon, tax, legal, and special constraints.", "Estimate expected returns, risks, and correlations consistently.", "Construct and evaluate portfolios in total, not security by security.", "Monitor, rebalance, and document changes."], "formulas": [["Portfolio expected return", "Σ wiE(Ri)"], ["Two-asset variance", "w1²σ1²+w2²σ2²+2w1w2ρ12σ1σ2"], ["CAPM", "E(Ri)=Rf+βi[E(Rm)−Rf]"], ["Sharpe ratio", "(Portfolio return−risk-free rate)/portfolio standard deviation"]], "traps": ["Assuming more securities always means better diversification.", "Using total volatility instead of beta in CAPM.", "Ignoring liabilities and liquidity needs.", "Treating willingness as the only measure of risk tolerance.", "Rebalancing without considering costs and taxes."]}, "ethics": {"overview": "Ethics is tested through facts and conduct, not through slogans. Read the vignette carefully, identify the applicable duty, determine what the person knew or should have known, and select the action that best protects market integrity, clients, and the profession. Learn the Standards and apply them consistently, especially where conflicts, material nonpublic information, diligence, suitability, performance, and disclosure are involved.", "workflow": ["Identify the actor, client, employer, and affected market participants.", "Separate facts from assumptions.", "Identify the applicable law, code, or standard.", "Choose the stricter applicable requirement unless following it would violate law.", "Prefer prevention, disclosure, documentation, and escalation over silence."], "formulas": [], "traps": ["Assuming disclosure cures every conflict.", "Using material nonpublic information within mosaic analysis.", "Believing fair dealing requires simultaneous communication in every operational case.", "Guaranteeing returns or overstating performance.", "Failing to distinguish preparation to leave an employer from solicitation or misappropriation."]}}, "workedExamples": {"quant": [{"title": "Compound annual growth", "problem": "An investment rises from 80 to 100 over three years. Find the annual compound return.", "steps": ["Compute the growth multiple: 100/80 = 1.25.", "Take the cube root: 1.25^(1/3) ≈ 1.0772.", "Subtract 1."], "answer": "Approximately 7.72% per year.", "trap": "Do not divide the total 25% gain by three; compounding is nonlinear."}, {"title": "Hypothesis-test decision", "problem": "A two-sided test uses a 5% significance level and produces p = 0.032. What is the decision?", "steps": ["Compare p-value with α.", "0.032 < 0.05.", "Reject the null hypothesis."], "answer": "Reject H0 at the 5% level.", "trap": "This does not prove the alternative with certainty; it indicates the sample is sufficiently inconsistent with H0."}], "economics": [{"title": "Elastic demand and revenue", "problem": "Price rises by 5% and quantity demanded falls by 12%. What happens to total revenue?", "steps": ["Elasticity magnitude = 12%/5% = 2.4.", "Demand is elastic because the magnitude exceeds 1.", "Quantity falls proportionally more than price rises."], "answer": "Total revenue decreases.", "trap": "Use absolute elasticity when classifying elasticity."}, {"title": "Real interest rate", "problem": "A nominal interest rate is 6% and expected inflation is 2%. Estimate the real rate.", "steps": ["Use the approximation: nominal − expected inflation.", "6% − 2% = 4%."], "answer": "Approximately 4%.", "trap": "The exact Fisher relation gives a slightly different result."}], "corporate": [{"title": "Project NPV", "problem": "A project costs 100 today and pays 60 in one year and 60 in two years. Required return is 10%.", "steps": ["PV year 1 = 60/1.10 = 54.55.", "PV year 2 = 60/1.10² = 49.59.", "Total PV = 104.14.", "NPV = 104.14 − 100."], "answer": "NPV ≈ 4.14; accept if independent.", "trap": "Do not subtract financing interest from project cash flows when discounting at WACC."}, {"title": "Cash conversion cycle", "problem": "Inventory days are 45, receivable days 30, and payable days 25.", "steps": ["CCC = inventory days + receivable days − payable days.", "45 + 30 − 25 = 50."], "answer": "Cash conversion cycle = 50 days.", "trap": "Payable days are subtracted because supplier financing delays cash outflow."}], "fsa": [{"title": "Indirect CFO adjustment", "problem": "Net income is 120, depreciation is 20, and accounts receivable increases by 15.", "steps": ["Start with net income: 120.", "Add back noncash depreciation: +20.", "Subtract increase in receivables: −15."], "answer": "CFO before other adjustments = 125.", "trap": "An increase in an operating asset is a use of cash."}, {"title": "Inventory turnover", "problem": "COGS is 500, beginning inventory 90, ending inventory 110.", "steps": ["Average inventory = (90+110)/2 = 100.", "Turnover = 500/100."], "answer": "Inventory turnover = 5.0 times.", "trap": "Use average inventory when the denominator is a balance-sheet account measured over a period."}], "equity": [{"title": "Gordon growth valuation", "problem": "Next dividend is 3.00, required return 10%, perpetual growth 4%.", "steps": ["Use V0 = D1/(r−g).", "Denominator = 0.10−0.04 = 0.06.", "3/0.06 = 50."], "answer": "Estimated value = 50.", "trap": "The growth rate must be sustainable and below the required return."}, {"title": "Holding-period return", "problem": "A share is bought for 40, sold for 44, and pays a dividend of 1.", "steps": ["Price gain = 44−40 = 4.", "Total gain = 4+1 = 5.", "Return = 5/40."], "answer": "Holding-period return = 12.5%.", "trap": "Include distributions received during the holding period."}], "fixed": [{"title": "Duration estimate", "problem": "Modified duration is 5.2 and yield rises by 0.40%. Estimate the price change.", "steps": ["Convert yield change to decimal: 0.004.", "Approximate %ΔP = −5.2×0.004.", "= −0.0208."], "answer": "Price falls approximately 2.08%.", "trap": "Duration is a first-order estimate and is less precise for large yield changes."}, {"title": "Expected credit loss", "problem": "PD is 3%, recovery rate 40%, and exposure is 1,000,000.", "steps": ["LGD = 1−0.40 = 0.60.", "Expected loss = 0.03×0.60×1,000,000."], "answer": "Expected credit loss = 18,000.", "trap": "Do not multiply by recovery rate; use loss given default."}], "derivatives": [{"title": "Long call profit", "problem": "Call strike is 50, premium is 4, and expiration price is 58.", "steps": ["Payoff = max(0,58−50)=8.", "Profit = payoff−premium = 8−4."], "answer": "Profit = 4.", "trap": "Payoff and profit are not the same."}, {"title": "Long forward payoff", "problem": "Delivery price is 75 and expiration spot price is 69.", "steps": ["Long-forward payoff = ST−K.", "69−75 = −6."], "answer": "Loss of 6 per unit.", "trap": "Forward downside is not limited to an initial premium."}], "alternatives": [{"title": "Property capitalization", "problem": "A property has NOI of 900,000 and a capitalization rate of 7.5%.", "steps": ["Value = NOI/cap rate.", "900,000/0.075 = 12,000,000."], "answer": "Estimated property value = 12 million.", "trap": "Use stabilized NOI consistent with the selected cap rate."}, {"title": "Commodity futures return", "problem": "Spot return is 5%, roll yield −2%, collateral yield 3%.", "steps": ["Add the three conceptual components.", "5%−2%+3%."], "answer": "Approximate total return = 6%.", "trap": "Futures performance can differ materially from spot-price performance."}], "portfolio": [{"title": "Portfolio expected return", "problem": "A portfolio invests 60% in an asset expected to return 8% and 40% in one expected to return 4%.", "steps": ["Multiply each return by its weight.", "0.60×8% + 0.40×4%.", "4.8%+1.6%."], "answer": "Expected portfolio return = 6.4%.", "trap": "Expected return is a weighted average; portfolio risk is not."}, {"title": "CAPM required return", "problem": "Risk-free rate is 3%, beta 1.2, and market risk premium 5%.", "steps": ["Use Rf+β×market risk premium.", "3%+1.2×5%.", "3%+6%."], "answer": "Required return = 9%.", "trap": "Use market risk premium, not expected market return, in the multiplication term."}], "ethics": [{"title": "Material nonpublic information", "problem": "An analyst learns privately that a listed company will lose its largest customer. The information is likely price-sensitive.", "steps": ["Assess materiality: likely to affect investor decisions or price.", "Assess public status: it was learned privately.", "Do not trade, recommend, or cause others to trade."], "answer": "Treat it as material nonpublic information and refrain from acting.", "trap": "Disclosure to a supervisor does not make the information public."}, {"title": "Conflict disclosure", "problem": "An analyst owns shares in a company being recommended to clients.", "steps": ["Identify the conflict.", "Disclose it prominently before clients rely on the recommendation.", "Maintain objective and independent analysis."], "answer": "Prominent disclosure is required; additional controls may also be appropriate.", "trap": "Disclosure does not excuse biased research or inadequate diligence."}]}, "fsaLessons": {"0": {"title": "Introduction to Financial Statement Analysis", "summary": "Financial statement analysis converts reported information into judgments about performance, financial position, cash-generation ability, risk, and value. A disciplined analyst defines the purpose, gathers reliable information, adjusts for comparability, analyzes relationships and trends, interprets the results, communicates conclusions, and monitors changes.", "mustKnow": ["The six-step framework: define purpose and context; collect data; process data; analyze and interpret; develop and communicate conclusions; follow up.", "Financial statements are only one source. Notes, management commentary, regulatory filings, earnings calls, industry data, credit reports, and macroeconomic information can materially change the conclusion.", "An audit opinion provides assurance about conformity with the reporting framework; it does not guarantee profitability, solvency, or absence of all fraud.", "Accounting standards influence recognition, measurement, presentation, and disclosure. Comparability may require analyst adjustments."], "detailed": [{"heading": "Purpose and context", "text": "Begin with a precise question. Equity analysis may focus on sustainable earnings and valuation; credit analysis may focus on liquidity, leverage, covenant capacity, and downside protection. The time horizon, benchmark, and required level of detail determine which data and tools are appropriate."}, {"heading": "Information hierarchy", "text": "Primary statements provide structured totals, but notes often explain accounting policies, estimates, segment data, commitments, contingencies, maturity schedules, and risks. Management commentary provides strategy and outlook but may contain optimistic bias. External sources help test management’s narrative."}, {"heading": "Audit reports", "text": "An unmodified opinion means the statements are presented fairly in material respects under the applicable framework. Qualified, adverse, or disclaimer opinions require close attention. Key audit matters can identify areas involving significant judgment, but they do not replace independent analysis."}, {"heading": "Analyst adjustments", "text": "When firms use different policies or classifications, an analyst may restate items to improve comparability. Adjustments should be transparent, internally consistent, and supported by disclosures rather than arbitrary assumptions."}], "table": {"headers": ["Source", "Primary value", "Main limitation"], "rows": [["Financial statements", "Standardized performance, position, and cash-flow data", "Aggregation and accounting-policy effects"], ["Notes", "Policies, estimates, commitments, segment and risk detail", "Complexity and delayed disclosure"], ["Management commentary", "Strategy, drivers, outlook, nonfinancial indicators", "Potential optimism and selective emphasis"], ["Audit report", "Independent assurance and highlighted judgment areas", "Not a guarantee of future success or fraud-free reporting"], ["External data", "Industry, economy, competitors, market expectations", "May use inconsistent definitions or estimates"]]}, "worked": [{"problem": "A lender is deciding whether to renew a one-year credit facility. Which analysis objective should receive the greatest emphasis?", "solution": ["Define the decision: short-term lending renewal.", "Identify the key risks: liquidity, near-term cash flow, refinancing, collateral, and covenant compliance.", "Prioritize current assets and liabilities, operating cash flow, unused facilities, debt maturities, and stress scenarios."], "answer": "Emphasize near-term liquidity and debt-servicing capacity rather than long-horizon equity valuation."}, {"problem": "Two companies report identical operating profit, but one capitalizes development costs while the other expenses them.", "solution": ["Recognize that capitalization increases current assets and current profit relative to immediate expensing.", "Review notes for policy and amortization details.", "Restate or supplement ratios to place both firms on a more comparable basis."], "answer": "Reported profit is not directly comparable without adjusting for the accounting-policy difference."}], "traps": ["Reading only the face of the statements and ignoring notes.", "Treating audited statements as proof of financial strength.", "Beginning ratio calculations before defining the analytical purpose.", "Using management-defined metrics without reconciling them to reported figures."], "memory": "P-C-P-A-C-F: Purpose, Collect, Process, Analyze, Communicate, Follow up."}, "1": {"title": "Analyzing Income Statements", "summary": "The income statement reports performance over a period. Exam questions often test revenue and expense recognition, capitalization versus expensing, nonrecurring items, earnings per share, common-size analysis, and whether reported earnings are sustainable.", "mustKnow": ["Revenue is recognized when the reporting criteria are satisfied, not necessarily when cash is collected.", "Capitalizing a cost initially raises assets and profit relative to expensing; later amortization or depreciation reduces future profit.", "Nonrecurring items should be evaluated for persistence and classification rather than automatically ignored.", "Basic EPS uses weighted-average common shares. Diluted EPS includes dilutive potential common shares but excludes antidilutive instruments.", "Common-size income statements express each item as a percentage of revenue."], "detailed": [{"heading": "Revenue recognition", "text": "Analyze the timing, amount, uncertainty, contract terms, returns, warranties, and remaining performance obligations. Aggressive recognition can pull future revenue into the current period, increase receivables or contract assets, and weaken cash conversion."}, {"heading": "Expense recognition and capitalization", "text": "Costs that create probable future benefits may be capitalized when the framework permits. Immediate expensing lowers current profit and assets. Capitalization raises current profit but creates future depreciation, amortization, or impairment charges."}, {"heading": "Nonrecurring and unusual items", "text": "Discontinued operations are separately presented when criteria are met. Restructuring, litigation, asset sales, and impairments may be unusual but can recur economically. Normalize earnings only after understanding the business and management’s history."}, {"heading": "EPS", "text": "Basic EPS equals income available to common shareholders divided by weighted-average common shares. Diluted EPS assumes conversion or exercise of dilutive instruments using the applicable method. Antidilutive effects are excluded."}, {"heading": "Margin analysis", "text": "Gross margin reflects pricing, product mix, and input costs. Operating margin also incorporates operating efficiency and cost structure. Net margin includes financing, tax, and nonoperating effects."}], "table": {"headers": ["Choice/event", "Current-period profit", "Assets", "Future expense"], "rows": [["Expense immediately", "Lower", "Lower", "None from the item"], ["Capitalize", "Higher", "Higher", "Depreciation/amortization or impairment"], ["Accelerate revenue", "Higher", "Often higher receivables/contract assets", "May reduce future revenue"], ["Impair asset", "Lower", "Lower", "Lower future depreciation may follow"]]}, "worked": [{"problem": "Net income is 2.4 million, preferred dividends are 0.2 million, and weighted-average common shares are 1.1 million.", "solution": ["Income available to common = 2.4−0.2 = 2.2 million.", "Basic EPS = 2.2/1.1."], "answer": "Basic EPS = 2.00."}, {"problem": "A firm capitalizes 600,000 of eligible costs and amortizes them straight-line over three years. Compare year-one pretax profit with immediate expensing, assuming a full year of amortization.", "solution": ["Immediate expense = 600,000.", "Capitalized amortization = 600,000/3 = 200,000.", "Difference = 400,000."], "answer": "Year-one pretax profit is 400,000 higher under capitalization."}, {"problem": "Revenue is 1,000, COGS 620, operating expenses 230, interest 30, and tax 24.", "solution": ["Gross profit = 380; gross margin = 38%.", "Operating profit = 150; operating margin = 15%.", "Pretax profit = 120; net income = 96; net margin = 9.6%."], "answer": "Gross margin 38%, operating margin 15%, net margin 9.6%."}], "traps": ["Using ending shares instead of weighted-average shares.", "Including antidilutive instruments in diluted EPS.", "Assuming every 'one-time' charge should be removed.", "Confusing cash collection with revenue recognition.", "Ignoring future amortization created by capitalization."], "memory": "Revenue timing, Expense timing, Persistence, EPS, Margins: REPEM."}, "2": {"title": "Analyzing Balance Sheets", "summary": "The balance sheet reports resources, obligations, and owners’ claims at a point in time. Analysis focuses on measurement bases, liquidity, solvency, intangible assets, goodwill, financial instruments, noncurrent liabilities, and common-size relationships.", "mustKnow": ["Assets and liabilities may be measured using historical cost, amortized cost, fair value, or other bases.", "Internally generated intangible assets are often treated differently from purchased intangibles, reducing comparability.", "Goodwill arises in a business combination and is tested for impairment rather than treated as a separable operating asset.", "Financial instruments require attention to classification, measurement, credit losses, and fair-value disclosures.", "Common-size balance sheets express each item as a percentage of total assets."], "detailed": [{"heading": "Intangible assets", "text": "Purchased identifiable intangibles are recognized when criteria are met. Finite-lived intangibles are amortized; indefinite-lived intangibles are tested for impairment. Internally generated brands, customer relationships, and similar resources may be economically important even when not recognized."}, {"heading": "Goodwill", "text": "Goodwill equals the excess of acquisition consideration and relevant recognized interests over the fair value of identifiable net assets under the applicable framework. It is not amortized under IFRS or US GAAP for public-company reporting, but is tested for impairment. Large goodwill balances can signal acquisition dependence."}, {"heading": "Financial instruments", "text": "Measurement depends on the instrument and classification. Analysts should distinguish contractual cash-flow assets, fair-value exposures, derivatives, impairment allowances, and items recognized through profit, OCI, or equity."}, {"heading": "Noncurrent liabilities", "text": "Debt analysis requires coupon, maturity, security, covenants, currency, fixed or floating rates, and off-balance-sheet commitments. The face amount alone does not describe refinancing or interest-rate risk."}, {"heading": "Common-size analysis", "text": "Scaling by total assets makes structure comparable across firms and over time. Interpretation still requires business context; a bank and a manufacturer naturally have different structures."}], "table": {"headers": ["Item", "Key analytical issue", "Possible warning"], "rows": [["Goodwill", "Acquisition assumptions and impairment testing", "Goodwill large relative to equity"], ["Intangibles", "Useful life, amortization, recognition differences", "Frequent impairment or aggressive capitalization"], ["Receivables", "Collectability and revenue quality", "Receivables growing faster than sales"], ["Debt", "Maturity, rates, covenants, currency", "Near-term maturity concentration"], ["Provisions", "Estimate uncertainty and timing", "Repeated reversals or weak disclosure"]]}, "worked": [{"problem": "Total assets are 500, inventory is 75, receivables 100, PPE 180, and goodwill 60. Calculate selected common-size percentages.", "solution": ["Inventory: 75/500 = 15%.", "Receivables: 100/500 = 20%.", "PPE: 180/500 = 36%.", "Goodwill: 60/500 = 12%."], "answer": "15%, 20%, 36%, and 12%, respectively."}, {"problem": "A company acquires a target for 300. Fair value of identifiable assets is 360 and liabilities 110.", "solution": ["Identifiable net assets = 360−110 = 250.", "Goodwill = 300−250."], "answer": "Goodwill = 50."}, {"problem": "Current assets are 240, inventory 80, and current liabilities 160.", "solution": ["Current ratio = 240/160 = 1.50.", "Quick ratio = (240−80)/160 = 1.00."], "answer": "Current ratio 1.50; quick ratio 1.00."}], "traps": ["Treating book value as market value.", "Assuming unrecognized internally generated intangibles have no economic value.", "Ignoring maturity schedules and covenant disclosures.", "Comparing common-size balances across unrelated business models without context."], "memory": "I-G-F-L-C: Intangibles, Goodwill, Financial instruments, Liabilities, Common size."}, "3": {"title": "Analyzing Statements of Cash Flows I", "summary": "The cash-flow statement reconciles beginning and ending cash by classifying cash flows as operating, investing, or financing. The direct and indirect methods differ only in presenting operating cash flow; total operating cash flow is the same when correctly prepared.", "mustKnow": ["Operating cash flow generally relates to core operations and working capital.", "Investing cash flow generally includes acquisition and disposal of long-term assets and investments.", "Financing cash flow generally includes transactions with debt and equity capital providers.", "The indirect method begins with net income and adjusts for noncash items, nonoperating items, and working-capital changes.", "IFRS and US GAAP differ in permitted classification of interest and dividends."], "detailed": [{"heading": "Link between statements", "text": "Cash changes arise from transactions recorded across the income statement and balance sheet. For example, credit sales increase revenue and receivables without immediate cash. Buying equipment uses investing cash while creating a balance-sheet asset."}, {"heading": "Indirect operating cash flow", "text": "Start with net income. Add back noncash expenses such as depreciation. Remove gains and losses whose cash effects belong in investing or financing. Subtract increases in operating assets and add increases in operating liabilities."}, {"heading": "Direct operating cash flow", "text": "The direct method reports major cash receipts and payments, such as cash collected from customers, cash paid to suppliers and employees, and taxes paid. It provides intuitive information about operating cash sources and uses."}, {"heading": "Classification differences", "text": "Under US GAAP, interest paid and received are operating; dividends received are operating; dividends paid are financing. IFRS allows specified policy choices for interest and dividends, applied consistently. Always use the classification stated or required by the question."}], "table": {"headers": ["Change", "Indirect CFO adjustment"], "rows": [["Operating asset increases", "Subtract"], ["Operating asset decreases", "Add"], ["Operating liability increases", "Add"], ["Operating liability decreases", "Subtract"], ["Noncash expense", "Add back"], ["Gain included in net income", "Subtract"], ["Loss included in net income", "Add"]]}, "worked": [{"problem": "Net income 150; depreciation 25; gain on equipment sale 8; receivables increase 12; inventory decreases 5; payables decrease 7.", "solution": ["Start 150.", "Add depreciation +25.", "Subtract gain −8.", "Subtract receivable increase −12.", "Add inventory decrease +5.", "Subtract payable decrease −7."], "answer": "CFO = 153."}, {"problem": "Sales are 900. Receivables increase from 70 to 95. Calculate cash collected from customers, assuming no other relevant items.", "solution": ["Increase in receivables = 25.", "Cash collected = sales−increase in receivables.", "900−25."], "answer": "Cash collected = 875."}, {"problem": "COGS is 500, inventory rises by 30, and payables rise by 20. Estimate cash paid to suppliers.", "solution": ["Purchases = COGS + increase in inventory = 530.", "Cash paid = purchases − increase in payables = 510."], "answer": "Cash paid to suppliers = 510."}], "traps": ["Reversing working-capital signs.", "Leaving a gain in CFO while also showing sale proceeds in investing cash flow.", "Assuming direct and indirect methods produce different CFO totals.", "Applying IFRS classification choices as if they were mandatory."], "memory": "Assets opposite; liabilities same: asset increase subtracts, liability increase adds."}, "4": {"title": "Analyzing Statements of Cash Flows II", "summary": "Cash-flow analysis evaluates the quality, sustainability, and allocation of cash. Analysts use common-size statements, free cash flow, coverage ratios, and comparisons between earnings and operating cash flow to assess financial flexibility.", "mustKnow": ["Common-size cash-flow statements can scale items by revenue or total inflows/outflows to reveal structural changes.", "FCFF is cash available to all capital providers after operating expenses, taxes, and required investment.", "FCFE is cash available to common equity after investment and net borrowing.", "Persistent divergence between net income and CFO requires explanation.", "Coverage ratios connect cash generation with interest, debt, or capital expenditure commitments."], "detailed": [{"heading": "Cash-flow quality", "text": "High-quality earnings are generally supported by cash, but temporary working-capital movements can create legitimate differences. Analyze multi-period trends, business seasonality, growth investment, and classification choices before concluding that earnings quality is weak."}, {"heading": "FCFF and FCFE", "text": "A common starting formulation is FCFF = CFO + after-tax interest − capital expenditure when interest paid is included in CFO. FCFE = CFO − capital expenditure + net borrowing. Exact formulations depend on the starting data and classification."}, {"heading": "Coverage and performance ratios", "text": "Operating cash flow to debt, cash interest coverage, and CFO margin help evaluate debt capacity and cash profitability. Definitions may vary, so state the numerator and denominator and use them consistently."}, {"heading": "Common-size analysis", "text": "Expressing CFO, capital expenditure, and financing flows as percentages of revenue can reveal whether growth is becoming more cash intensive, whether debt funds distributions, or whether operating cash supports investment."}], "table": {"headers": ["Metric", "Illustrative formula", "Interpretation"], "rows": [["CFO margin", "CFO/revenue", "Cash generated per unit of revenue"], ["CFO to debt", "CFO/average or ending debt", "Cash debt-servicing capacity"], ["FCFF", "CFO + after-tax interest − capex", "Cash available to debt and equity"], ["FCFE", "CFO − capex + net borrowing", "Cash available to common equity"], ["Cash reinvestment", "Capex/CFO", "Share of operating cash reinvested"]]}, "worked": [{"problem": "CFO is 220, interest paid 30, tax rate 25%, and capital expenditure 90. Interest paid is classified in CFO.", "solution": ["After-tax interest = 30×(1−0.25)=22.5.", "FCFF = 220+22.5−90."], "answer": "FCFF = 152.5."}, {"problem": "CFO is 220, capex 90, debt issued 50, and debt repaid 20.", "solution": ["Net borrowing = 50−20 = 30.", "FCFE = 220−90+30."], "answer": "FCFE = 160."}, {"problem": "Revenue is 1,100, CFO 165, and total debt 600.", "solution": ["CFO margin = 165/1,100 = 15%.", "CFO-to-debt = 165/600 = 27.5%."], "answer": "CFO margin 15%; CFO-to-debt 27.5%."}], "traps": ["Adding full interest rather than after-tax interest when deriving FCFF from CFO.", "Using debt issuance instead of net borrowing for FCFE.", "Calling all negative investing cash flow bad; productive capex may support growth.", "Using one-year CFO without considering seasonality and working-capital cycles."], "memory": "FCFF serves Firm; FCFE serves Equity."}, "5": {"title": "Analysis of Inventories", "summary": "Inventory accounting affects cost of goods sold, profit, assets, taxes, cash flow timing, and key ratios. The analyst must understand the cost-flow assumption, write-down rules, disclosure quality, and how changes in prices influence comparability.", "mustKnow": ["Inventory cost includes purchase and conversion costs needed to bring inventory to its present location and condition.", "FIFO assigns older costs to COGS and newer costs to ending inventory.", "Weighted-average cost smooths price changes across units.", "LIFO is permitted under US GAAP but prohibited under IFRS.", "Inventory write-downs reduce assets and profit; IFRS may permit reversal when value recovers, while US GAAP rules are more restrictive.", "Ratios must be interpreted together: turnover, days inventory, gross margin, current ratio, and cash conversion cycle."], "detailed": [{"heading": "Cost-flow assumptions", "text": "Cost-flow assumptions determine which costs are assigned to COGS and which remain in ending inventory. They need not match the physical movement of goods. In rising prices, FIFO usually produces lower COGS, higher ending inventory, higher gross profit, and higher taxes than LIFO."}, {"heading": "FIFO versus weighted average", "text": "FIFO preserves recent costs in ending inventory and older costs in COGS. Weighted average blends costs and normally produces results between FIFO and LIFO when input prices change consistently."}, {"heading": "LIFO reserve and comparability", "text": "A US GAAP company using LIFO may disclose a LIFO reserve. Adding the reserve to LIFO inventory approximates FIFO inventory. Changes in the reserve can be used to estimate FIFO COGS from LIFO COGS."}, {"heading": "Write-downs and reversals", "text": "When inventory value falls below its carrying amount, a write-down reduces inventory and profit. A later recovery may be reversed under IFRS up to the original write-down, but reversal is generally not permitted under US GAAP for inventory measured under the relevant lower-of-cost rule."}, {"heading": "Ratio interpretation", "text": "High turnover can indicate efficiency or inadequate stock. Low turnover can indicate excess, obsolete, or slow-moving inventory. Compare with margins, sales growth, stockouts, industry practice, and disclosures."}], "table": {"headers": ["Rising prices", "FIFO compared with LIFO", "Likely effect"], "rows": [["COGS", "Lower", "Higher gross and operating profit"], ["Ending inventory", "Higher", "Higher current assets and equity"], ["Taxes", "Higher", "Lower operating cash flow from higher tax payments"], ["Current ratio", "Higher", "Stronger reported liquidity"], ["Inventory turnover", "Usually lower", "Higher average inventory denominator"]]}, "worked": [{"problem": "Beginning inventory is 100 units at 10. Purchases are 100 units at 14. The company sells 120 units. Calculate FIFO COGS and ending inventory.", "solution": ["FIFO COGS uses the oldest 100 units at 10 = 1,000.", "Add 20 units from the new purchase at 14 = 280.", "FIFO COGS = 1,280.", "Ending inventory is the remaining 80 units at 14 = 1,120."], "answer": "FIFO COGS = 1,280; ending inventory = 1,120."}, {"problem": "Using the same data, calculate weighted-average COGS and ending inventory.", "solution": ["Total cost = 1,000 + 1,400 = 2,400.", "Average cost per unit = 2,400 / 200 = 12.", "COGS = 120 × 12 = 1,440.", "Ending inventory = 80 × 12 = 960."], "answer": "Weighted-average COGS = 1,440; ending inventory = 960."}, {"problem": "LIFO inventory is 700 and the LIFO reserve is 180. Estimate FIFO inventory.", "solution": ["FIFO inventory ≈ LIFO inventory + LIFO reserve.", "700 + 180 = 880."], "answer": "Estimated FIFO inventory = 880."}], "traps": ["Assuming cost flow must equal physical flow.", "Forgetting that higher reported profit can also produce higher taxes.", "Using ending inventory rather than average inventory in turnover without checking the question.", "Treating a falling turnover ratio as automatically bad without considering deliberate stock build.", "Applying IFRS inventory reversal rules to US GAAP."], "memory": "Rising prices: FIFO leaves the newest, higher costs on the balance sheet."}, "6": {"title": "Analysis of Long-Term Assets", "summary": "Long-term asset accounting affects current profit, future expenses, assets, cash-flow classification, and performance ratios. The central analytical questions are whether a cost is capitalized or expensed, how the asset is depreciated or amortized, whether impairment is recognized, and how revaluation or disposal affects comparability.", "mustKnow": ["Capitalizing a cost raises current assets and current profit relative to immediate expensing.", "Depreciation allocates depreciable cost over the expected useful life; it is not a valuation method.", "Accelerated depreciation records more expense early and less later than straight-line depreciation.", "Changes in useful life or residual value are generally changes in accounting estimates applied prospectively.", "Impairment reduces carrying value and current profit.", "IFRS permits a revaluation model for some long-lived assets; US GAAP generally uses historical cost less depreciation and impairment.", "Cash paid to acquire long-term assets is generally investing cash flow."], "detailed": [{"heading": "Capitalization versus expensing", "text": "Capitalization recognizes an asset and delays expense through depreciation or amortization. Immediate expensing lowers current profit and assets but avoids future allocation expense. Over the full life, total pretax expense is normally the same absent impairment or disposal differences."}, {"heading": "Depreciation methods", "text": "Straight-line produces equal periodic expense. Accelerated methods record higher expense in earlier years. Units-of-production links expense to actual use. Method choice affects timing of profit, assets, and ratios but not total depreciable cost."}, {"heading": "Impairment", "text": "Impairment occurs when carrying amount is not recoverable under the applicable framework. Recognition lowers assets and profit. Future depreciation may decline because the depreciable base is lower. IFRS and US GAAP differ in testing and reversals."}, {"heading": "Revaluation", "text": "IFRS may permit property, plant, and equipment to be carried at revalued amounts if the policy is applied consistently to a class of assets. Upward revaluation usually affects OCI and equity subject to prior decreases. US GAAP generally does not permit upward revaluation for operating long-lived assets."}, {"heading": "Analytical adjustments", "text": "Compare asset age, remaining useful life, capital expenditure, depreciation, maintenance, impairment history, and asset turnover. Low depreciation relative to gross assets may indicate older assets or aggressive useful-life assumptions."}], "table": {"headers": ["Accounting choice", "Early-period effect", "Later-period effect"], "rows": [["Capitalize rather than expense", "Higher profit and assets", "Depreciation/amortization lowers future profit"], ["Accelerated rather than straight-line depreciation", "Lower early profit and assets", "Higher later profit relative to straight-line"], ["Longer useful life", "Lower annual depreciation", "Higher carrying value and profit"], ["Impairment", "Lower current profit and assets", "Potentially lower future depreciation"], ["Upward revaluation under IFRS", "Higher assets and equity", "Potentially higher future depreciation"]]}, "worked": [{"problem": "Equipment costs 120,000, residual value is 20,000, and useful life is five years. Calculate straight-line annual depreciation.", "solution": ["Depreciable base = 120,000 − 20,000 = 100,000.", "Annual depreciation = 100,000 / 5."], "answer": "Annual depreciation = 20,000."}, {"problem": "An eligible 90,000 cost is capitalized and amortized over three years. Compare first-year pretax profit with immediate expensing.", "solution": ["Immediate-expense method records 90,000 expense.", "Capitalization records 30,000 first-year amortization.", "Difference = 60,000."], "answer": "First-year pretax profit is 60,000 higher under capitalization."}, {"problem": "An asset has carrying amount 500,000 and is impaired to 380,000.", "solution": ["Impairment loss = 500,000 − 380,000.", "The loss reduces profit and the asset's carrying amount."], "answer": "Impairment loss = 120,000."}], "traps": ["Treating depreciation as a cash outflow.", "Ignoring residual value when calculating depreciable cost.", "Assuming a longer useful life reflects stronger economics rather than an accounting estimate.", "Forgetting that impairment can improve future margins by reducing future depreciation.", "Applying IFRS revaluation or reversal rules to US GAAP."], "memory": "Capitalize now, expense later; expense now, no asset later."}}, "detailedLessons": {"ethics:1": {"title": "Ethics and Trust in the Investment Profession", "summary": "Investment professionals handle other people's capital and information. Trust lowers transaction costs, supports market participation, and depends on competence, integrity, transparency, and putting client interests ahead of personal gain. Ethical decisions require more than legal compliance because conduct can be legal yet still damage clients, markets, or the profession.", "mustKnow": ["Ethics concerns principles of right conduct; professionalism applies those principles to a specialized occupation.", "Trust is an economic asset: it supports market participation, efficient capital allocation, and lower monitoring costs.", "Legal conduct is not automatically ethical conduct.", "Situational influences—including incentives, authority pressure, group norms, and time pressure—can impair judgment.", "A structured ethical decision framework improves consistency and defensibility."], "detailed": [{"heading": "Why trust matters", "text": "Investors often cannot directly observe the quality of research, execution, valuation, or risk management. They therefore rely on professional competence and honesty. A breakdown in trust can raise the cost of capital, reduce market participation, and harm both clients and institutions."}, {"heading": "Law versus ethics", "text": "Law defines minimum enforceable requirements. Ethics can demand more, especially where rules are incomplete, outdated, or silent. An action may satisfy the literal law but still exploit clients or undermine market integrity."}, {"heading": "Situational influences", "text": "People may rationalize misconduct when targets are aggressive, supervisors apply pressure, colleagues normalize questionable behavior, or accountability is weak. Recognizing these influences before acting helps prevent ethical fading."}, {"heading": "Ethical decision process", "text": "Identify relevant facts, stakeholders, duties, conflicts, and alternatives. Consider short- and long-term consequences, seek guidance where appropriate, decide, document the rationale, and reflect on the outcome."}], "table": {"headers": ["Concept", "Meaning", "Exam focus"], "rows": [["Ethics", "Principles governing right conduct", "What should be done, not only what is legal"], ["Professionalism", "Specialized competence plus duties to clients and society", "Higher standards and accountability"], ["Trust", "Confidence that another party will act competently and honestly", "Foundation of investment markets"], ["Situational influence", "Pressure or context affecting judgment", "Incentives, authority, group norms"], ["Ethical framework", "Structured method for reaching a defensible decision", "Facts, stakeholders, duties, alternatives, consequences"]]}, "worked": [{"problem": "A research analyst is told that publishing a cautious forecast will reduce the team's bonus. No law requires a particular forecast.", "solution": ["Identify the conflict between objective analysis and compensation pressure.", "Recognize that legal silence does not remove the ethical duty to provide honest, well-supported analysis.", "Use independent assumptions, document the basis, and escalate improper pressure."], "answer": "The analyst should preserve objectivity and a reasonable basis despite the incentive."}, {"problem": "A portfolio manager notices colleagues routinely omitting small fees from performance presentations because 'everyone does it.'", "solution": ["Group practice is a situational influence, not a justification.", "Omitting fees can mislead clients about realized performance.", "The manager should correct the presentation and raise the control weakness."], "answer": "Industry or team norms do not excuse misleading conduct."}], "traps": ["Assuming anything legal is automatically ethical.", "Treating good intentions as a substitute for competence and diligence.", "Ignoring small conflicts because the financial amount is limited.", "Following a supervisor's instruction without independently assessing professional duties.", "Focusing only on immediate consequences and ignoring long-term trust."], "memory": "FACTS: Facts, Affected stakeholders, Conflicts, Tests and standards, Solutions."}, "ethics:2": {"title": "Code of Ethics and Standards of Professional Conduct", "summary": "The Code expresses broad professional principles; the Standards translate them into enforceable areas of conduct. Candidates should know the seven Standards, identify which duty applies to a scenario, and select preventive or corrective action. The Code and Standards do not guarantee perfect outcomes; they require integrity, competence, diligence, independence, and fair treatment.", "mustKnow": ["The Code includes integrity, competence, diligence, respect, independent judgment, client interests, market integrity, and professional improvement.", "The seven Standards cover Professionalism; Integrity of Capital Markets; Duties to Clients; Duties to Employers; Investment Analysis, Recommendations, and Actions; Conflicts of Interest; and Responsibilities as a CFA Institute Member or Candidate.", "When applicable law and the Standards differ, follow the stricter requirement unless doing so violates law.", "Members and candidates must not knowingly participate in violations and may need to dissociate.", "Disclosure helps manage some conflicts but does not cure dishonest, biased, or inadequately supported conduct."], "detailed": [{"heading": "Code versus Standards", "text": "The Code provides overarching ideals. The Standards organize concrete professional duties. Exam questions typically present facts and ask which Standard is implicated or what action is most appropriate."}, {"heading": "Knowledge of law", "text": "Understand and comply with applicable laws, rules, regulations, and the Code and Standards. Where requirements conflict, use the stricter rule unless prohibited by law. Do not participate in violations; dissociate when necessary."}, {"heading": "Prevention and documentation", "text": "Strong conduct includes written policies, conflict registers, approval processes, restricted lists, independent review, record retention, and timely escalation. Prevention is usually better than disclosure after harm occurs."}, {"heading": "Applying multiple Standards", "text": "One scenario can involve several duties. For example, biased issuer-paid research may involve independence, reasonable basis, communication, and conflict disclosure. Select the answer that addresses the most direct violation and effective response."}], "table": {"headers": ["Standard", "Core duty", "Typical trigger"], "rows": [["I Professionalism", "Law, independence, objectivity, truthful conduct", "Gifts, pressure, misrepresentation, misconduct"], ["II Capital Markets", "Protect market integrity", "Inside information, manipulation"], ["III Clients", "Loyalty, prudence, fairness, suitability, confidentiality", "Allocation, recommendations, client data"], ["IV Employers", "Loyalty and responsible supervision", "Outside compensation, departure, oversight"], ["V Analysis", "Diligence, reasonable basis, clear communication, records", "Research and recommendations"], ["VI Conflicts", "Disclose and manage conflicts", "Ownership, compensation, referral fees"], ["VII CFA responsibilities", "Protect program and designation integrity", "Exam conduct, designation use"]]}, "worked": [{"problem": "Local law permits conduct that the Standards prohibit.", "solution": ["Identify both applicable requirements.", "Determine which is stricter.", "Follow the stricter Standards requirement unless doing so would violate applicable law."], "answer": "Apply the stricter professional requirement."}, {"problem": "A junior analyst discovers that a supervisor is directing staff to use unsupported estimates in client reports.", "solution": ["Do not knowingly participate.", "Raise the concern through appropriate internal channels.", "Dissociate from the activity if the violation cannot be corrected."], "answer": "Refusal, escalation, and dissociation may be required."}], "traps": ["Believing disclosure permits knowingly false analysis.", "Assuming only the person who initiated misconduct can violate the Standards.", "Following the less strict rule because it is local law.", "Waiting until a client complains before addressing a known control failure.", "Treating the seven Standards as mutually exclusive."], "memory": "Markets need Professional Clients, Employers, Analysis, Conflicts, and CFA responsibility: I–VII."}, "quant:3": {"title": "The Time Value of Money in Finance", "summary": "Time value of money converts cash flows occurring at different dates into equivalent values at one date. The essential tools are compounding, discounting, annuities, perpetuities, uneven cash flows, and solving for rates or periods. Always draw a timeline, match the rate to the cash-flow frequency, and use consistent cash-flow signs.", "mustKnow": ["Future value compounds current money forward; present value discounts future money backward.", "Rates and periods must use the same frequency.", "Ordinary annuity payments occur at period end; annuity-due payments occur at period beginning.", "A perpetuity is an infinite level stream; a growing perpetuity grows at a constant rate below the discount rate.", "Net present value compares the present value of benefits with the present value of costs.", "On a financial calculator, inflows and outflows require opposite signs."], "detailed": [{"heading": "Compounding and discounting", "text": "FV = PV(1+r)^n and PV = FV/(1+r)^n. More periods or a higher positive rate increases future value and reduces present value. Discounting allows comparison of cash flows at a common date."}, {"heading": "Annuities", "text": "An ordinary annuity pays at period end. An annuity due pays one period earlier, so its present and future values equal the ordinary-annuity value multiplied by (1+r)."}, {"heading": "Perpetuities", "text": "A level perpetuity has PV = C/r. A growing perpetuity has PV = C1/(r−g), where C1 is the next-period cash flow and r must exceed g."}, {"heading": "Uneven cash flows and NPV", "text": "Discount each cash flow individually or use the calculator cash-flow worksheet. NPV equals the sum of present values, including the initial outflow."}, {"heading": "BA II Plus workflow", "text": "Clear TVM registers with 2nd CLR TVM. Set P/Y consistently. Enter N, I/Y, PV, PMT, and FV, leaving one unknown. Use opposite signs for cash paid and received. For uneven flows, use CF, enter CF0 and subsequent cash flows, then NPV."}], "table": {"headers": ["Cash-flow pattern", "Core relationship", "Key condition"], "rows": [["Single sum", "FV = PV(1+r)^n", "Rate and periods aligned"], ["Ordinary annuity PV", "PMT × [1−(1+r)^−n]/r", "Payments at period end"], ["Annuity due", "Ordinary annuity value × (1+r)", "Payments one period earlier"], ["Level perpetuity", "C/r", "First payment in one period"], ["Growing perpetuity", "C1/(r−g)", "r > g"], ["NPV", "Σ CFt/(1+r)^t", "Include CF0 at t=0"]]}, "worked": [{"problem": "Find the future value of 5,000 invested for four years at 6% annually.", "solution": ["FV = 5,000(1.06)^4.", "(1.06)^4 ≈ 1.262477.", "FV ≈ 6,312.38."], "answer": "Future value ≈ 6,312.38."}, {"problem": "Find the present value of 10,000 received in five years using an 8% discount rate.", "solution": ["PV = 10,000/(1.08)^5.", "(1.08)^5 ≈ 1.469328.", "PV ≈ 6,805.83."], "answer": "Present value ≈ 6,805.83."}, {"problem": "A perpetuity pays 300 annually, beginning one year from now. Required return is 5%.", "solution": ["PV = C/r.", "PV = 300/0.05."], "answer": "PV = 6,000."}, {"problem": "A project costs 1,000 and pays 600 in one year and 600 in two years. Required return is 10%.", "solution": ["PV1 = 600/1.10 = 545.45.", "PV2 = 600/1.10² = 495.87.", "Total PV = 1,041.32.", "NPV = 1,041.32 − 1,000."], "answer": "NPV ≈ 41.32."}], "traps": ["Using an annual rate with monthly periods without conversion.", "Forgetting to switch calculator mode between END and BGN.", "Entering PV and FV with the same sign.", "Using the current cash flow rather than next-period cash flow in a growing perpetuity.", "Applying the perpetuity formula when the discount rate is not greater than growth.", "Rounding intermediate values too early."], "memory": "Timeline, Frequency, Signs, Mode, Solve: TFSMS."}, "economics:0": {"title": "Demand, Supply, and Market Equilibrium", "summary": "Markets coordinate buyers and sellers through prices. Demand slopes downward because consumers generally buy less at higher prices; supply slopes upward because producers generally offer more at higher prices. Equilibrium occurs where quantity demanded equals quantity supplied. The exam frequently tests curve shifts, movements along curves, elasticity, price controls, taxes, and changes in surplus.", "mustKnow": ["A change in a good's own price causes movement along demand or supply; another determinant causes the curve to shift.", "Demand shifters include income, tastes, expectations, population, and prices of substitutes and complements.", "Supply shifters include input costs, technology, taxes, subsidies, expectations, and number of sellers.", "A shortage exists below equilibrium price; a surplus exists above equilibrium price.", "A binding price ceiling lies below equilibrium; a binding price floor lies above equilibrium.", "Elasticity measures responsiveness and helps predict revenue and tax-incidence effects."], "detailed": [{"heading": "Demand and quantity demanded", "text": "Demand describes the full relationship between price and quantity demanded, holding other factors constant. A price change causes movement along the demand curve. A change in income, preferences, expectations, or related-good prices shifts the curve."}, {"heading": "Supply and quantity supplied", "text": "Supply describes the relationship between price and quantity producers are willing to sell. A change in the product's own price causes movement along the curve. A change in input cost, technology, taxes, or producer expectations shifts supply."}, {"heading": "Equilibrium", "text": "At equilibrium, planned purchases equal planned sales. When price is below equilibrium, shortage creates upward pressure on price. When price is above equilibrium, surplus creates downward pressure."}, {"heading": "Elasticity", "text": "Price elasticity of demand equals percentage change in quantity demanded divided by percentage change in price. Demand is elastic when the absolute value exceeds one, inelastic when below one, and unit elastic when equal to one."}, {"heading": "Government intervention", "text": "A binding ceiling creates shortage; a binding floor creates surplus. Taxes create a wedge between buyer and seller prices. The less elastic side of the market bears more of the economic tax burden."}], "table": {"headers": ["Change", "Curve effect", "Likely equilibrium effect"], "rows": [["Consumer income rises for a normal good", "Demand shifts right", "Higher price and quantity"], ["Input costs rise", "Supply shifts left", "Higher price, lower quantity"], ["Technology improves", "Supply shifts right", "Lower price, higher quantity"], ["Substitute price rises", "Demand shifts right", "Higher price and quantity"], ["Binding price ceiling", "No curve shift", "Shortage"], ["Binding price floor", "No curve shift", "Surplus"]]}, "worked": [{"problem": "Demand is Qd = 100 − 2P and supply is Qs = 20 + 2P. Find equilibrium.", "solution": ["Set Qd = Qs.", "100 − 2P = 20 + 2P.", "80 = 4P, so P = 20.", "Substitute: Q = 100 − 40 = 60."], "answer": "Equilibrium price = 20; equilibrium quantity = 60."}, {"problem": "Price rises 5% and quantity demanded falls 15%. Classify elasticity and predict total revenue.", "solution": ["Elasticity magnitude = 15% / 5% = 3.", "Demand is elastic.", "Quantity falls proportionally more than price rises."], "answer": "Demand is elastic; total revenue falls."}, {"problem": "A tax is imposed in a market where demand is much less elastic than supply.", "solution": ["The less elastic side changes quantity less in response to price.", "That side has fewer alternatives.", "Consumers therefore bear more of the economic burden."], "answer": "Buyers bear the larger share of the tax."}], "traps": ["Calling a movement along a curve a shift.", "Ignoring whether a good is normal or inferior.", "Using signed elasticity instead of absolute value when classifying demand.", "Assuming the legal payer bears the entire economic tax burden.", "Treating a nonbinding price control as if it changes market outcomes."], "memory": "Own price moves; everything else shifts."}, "economics:1": {"title": "Consumer Choice and Market Equilibrium", "summary": "Consumer choice explains how limited income is allocated across goods to maximize utility. The optimal bundle occurs where the budget constraint is tangent to the highest attainable indifference curve, subject to corner solutions. Changes in price create substitution and income effects. Market demand aggregates individual demands.", "mustKnow": ["A budget constraint shows affordable combinations based on income and prices.", "Indifference curves represent combinations providing equal utility.", "For an interior optimum, marginal rate of substitution equals the price ratio.", "A price change creates both substitution and income effects.", "Normal goods have positive income effects; inferior goods have negative income effects.", "Market demand is the horizontal sum of individual demand curves."], "detailed": [{"heading": "Budget constraint", "text": "For goods X and Y, income equals PxX + PyY. The intercepts are income divided by each good's price. A change in income shifts the line in parallel; a price change rotates it."}, {"heading": "Indifference curves", "text": "Higher curves represent greater utility. Curves generally slope downward and are convex because consumers prefer balanced bundles and exhibit diminishing marginal rates of substitution."}, {"heading": "Consumer optimum", "text": "At an interior optimum, MRSxy = Px/Py. Equivalently, marginal utility per currency unit is equalized across goods. If tangency is impossible, a corner solution may occur."}, {"heading": "Substitution and income effects", "text": "When a good becomes cheaper, the substitution effect always increases demand for it relative to alternatives. The income effect depends on whether the good is normal or inferior."}, {"heading": "Market demand", "text": "At each price, add the quantities demanded by all consumers. Changes in population, income distribution, and preferences can shift aggregate demand."}], "table": {"headers": ["Change", "Budget-line effect", "Consumer implication"], "rows": [["Income rises", "Parallel outward shift", "More affordable bundles"], ["Price of X falls", "X-intercept moves outward", "X becomes relatively cheaper"], ["Price of Y rises", "Y-intercept moves inward", "Y becomes relatively more expensive"], ["Normal-good income rise", "Demand increases", "Positive income effect"], ["Inferior-good income rise", "Demand decreases", "Negative income effect"]]}, "worked": [{"problem": "Income is 120, Px = 10, and Py = 20. Find budget intercepts.", "solution": ["Maximum X = 120/10 = 12.", "Maximum Y = 120/20 = 6."], "answer": "X-intercept = 12; Y-intercept = 6."}, {"problem": "At a candidate bundle, MUx/Px = 4 and MUy/Py = 6.", "solution": ["Utility per currency unit is higher for Y.", "The consumer can increase utility by buying more Y and less X.", "Adjustment continues until the ratios are equal, subject to constraints."], "answer": "Shift spending toward Y."}], "traps": ["Confusing the slope of the budget line with income.", "Assuming every optimum must be a tangency.", "Forgetting that the substitution effect always moves toward the relatively cheaper good.", "Treating inferior goods as necessarily Giffen goods.", "Adding prices rather than quantities when constructing market demand."], "memory": "Best affordable bundle: highest curve touching the budget line."}, "economics:4": {"title": "Inflation, Interest Rates, and Monetary Relationships", "summary": "Inflation reduces purchasing power and affects nominal interest rates, investment returns, wages, and policy. Analysts must distinguish headline from core inflation, expected from unexpected inflation, and nominal from real rates. The Fisher relationship links nominal rates, real rates, and expected inflation.", "mustKnow": ["Inflation is a sustained increase in the general price level, not a one-time rise in one price.", "CPI measures the cost of a representative consumer basket and may contain substitution, quality, and new-product biases.", "Expected inflation tends to be incorporated into nominal rates and contracts.", "Unexpected inflation redistributes wealth between borrowers and lenders.", "Approximate real rate = nominal rate − expected inflation.", "Exact Fisher relation: (1 + nominal) = (1 + real)(1 + expected inflation)."], "detailed": [{"heading": "Inflation measures", "text": "Consumer price indexes track household-purchase baskets. GDP deflators cover domestically produced final goods and services. Core measures exclude volatile components to reveal underlying trends."}, {"heading": "Expected versus unexpected inflation", "text": "Expected inflation can be incorporated into wages, interest rates, and contracts. Unexpected inflation harms fixed-rate lenders and benefits fixed-rate borrowers because repayment occurs in less valuable money."}, {"heading": "Nominal and real rates", "text": "Nominal returns measure currency growth. Real returns measure purchasing-power growth. For moderate rates, real ≈ nominal − inflation. The exact relationship compounds both components."}, {"heading": "Interest-rate transmission", "text": "Central banks influence short-term nominal rates and financial conditions. Real rates depend on nominal policy, inflation expectations, risk premia, and market transmission."}], "table": {"headers": ["Concept", "Meaning", "Typical exam distinction"], "rows": [["Headline inflation", "Broad published measure", "Includes volatile components"], ["Core inflation", "Underlying trend measure", "Excludes selected volatile items"], ["Nominal rate", "Currency-unit return", "Includes inflation compensation"], ["Real rate", "Purchasing-power return", "Adjusts for inflation"], ["Expected inflation", "Anticipated price growth", "Often built into rates"], ["Unexpected inflation", "Inflation surprise", "Redistributes wealth"]]}, "worked": [{"problem": "Nominal return is 7% and inflation is 3%. Estimate the real return.", "solution": ["Approximate real return = 7% − 3%.", "Approximate result = 4%."], "answer": "Approximately 4%."}, {"problem": "Nominal rate is 8% and expected inflation is 3%. Compute the exact real rate.", "solution": ["1 + real = 1.08/1.03.", "Real = 1.0485437 − 1."], "answer": "Exact real rate ≈ 4.85%."}, {"problem": "Unexpected inflation rises above the rate built into a fixed-rate loan.", "solution": ["The lender receives fixed nominal payments.", "Those payments have lower purchasing power than expected.", "The borrower repays with less valuable money."], "answer": "Borrower benefits; lender loses."}], "traps": ["Subtracting actual inflation when the question asks about an ex ante real rate.", "Treating a relative price change as general inflation.", "Assuming CPI has no measurement bias.", "Using the approximation when the exact answer is required.", "Forgetting that unexpected inflation redistributes wealth."], "memory": "Nominal includes inflation; real removes it."}, "corporate:1": {"title": "Capital Budgeting and Project Evaluation", "summary": "Capital budgeting evaluates long-term investments using incremental after-tax cash flows and a discount rate appropriate to project risk. Net present value is the primary value-maximizing criterion. IRR, payback, discounted payback, and profitability index provide supporting information but can produce misleading rankings.", "mustKnow": ["Use incremental after-tax cash flows, not accounting profit.", "Include opportunity costs and externalities; exclude sunk costs.", "Financing costs are generally reflected in the discount rate, not deducted from project cash flows.", "Accept an independent project when NPV is positive.", "For mutually exclusive projects, choose the project with the highest positive NPV when rankings conflict.", "IRR may be unreliable with nonconventional cash flows or mutually exclusive projects.", "Profitability index is useful under capital rationing."], "detailed": [{"heading": "Incremental cash flow", "text": "Project analysis includes only cash flows that change because the project is undertaken. Relevant items include initial investment, working capital, operating cash flows, taxes, opportunity costs, side effects, terminal cash flow, and recovery of working capital."}, {"heading": "NPV", "text": "NPV equals the present value of future incremental cash flows minus the initial investment. A positive NPV means the project is expected to earn more than the required return and increase firm value."}, {"heading": "IRR", "text": "IRR is the discount rate that sets NPV to zero. For conventional independent projects, accept when IRR exceeds the required return. Multiple IRRs can occur when cash-flow signs change more than once."}, {"heading": "Payback methods", "text": "Payback measures time to recover the initial investment but ignores time value and later cash flows. Discounted payback addresses time value but still ignores cash flows after the cutoff."}, {"heading": "Profitability index", "text": "PI equals present value of future cash inflows divided by the initial investment. PI above one corresponds to positive NPV. Under capital rationing, PI can help rank value created per unit invested."}], "table": {"headers": ["Method", "Decision rule", "Main limitation"], "rows": [["NPV", "Accept if NPV > 0", "Requires appropriate discount rate"], ["IRR", "Accept if IRR > required return", "Multiple IRRs and ranking conflicts"], ["Payback", "Accept if within cutoff", "Ignores TVM and later cash flows"], ["Discounted payback", "Accept if within cutoff", "Ignores post-cutoff cash flows"], ["Profitability index", "Accept if PI > 1", "Can misrank mutually exclusive projects"]]}, "worked": [{"problem": "A project costs 100 and pays 45 annually for three years. Required return is 10%.", "solution": ["PV = 45/1.10 + 45/1.10² + 45/1.10³.", "PV ≈ 40.91 + 37.19 + 33.81 = 111.91.", "NPV = 111.91 − 100."], "answer": "NPV ≈ 11.91; accept if independent."}, {"problem": "A machine costs 200, creates annual after-tax operating cash flow of 70 for four years, and has salvage value 20. Required return is 8%.", "solution": ["Discount four operating cash flows of 70.", "PV operating cash flows ≈ 231.82.", "PV salvage = 20/(1.08)^4 ≈ 14.70.", "NPV = 231.82 + 14.70 − 200."], "answer": "NPV ≈ 46.52."}, {"problem": "A firm already spent 30 on a feasibility study before evaluating a project.", "solution": ["The expenditure has already occurred.", "It cannot be changed by accepting or rejecting the project.", "It is therefore not incremental."], "answer": "Exclude the 30 as a sunk cost."}, {"problem": "Project A has NPV 50 and PI 1.20; Project B has NPV 35 and PI 1.35. They are mutually exclusive and capital is not rationed.", "solution": ["For mutually exclusive projects, value maximization relies on NPV.", "A creates more absolute value."], "answer": "Choose Project A."}], "traps": ["Including sunk costs.", "Excluding opportunity costs because no cash invoice is paid.", "Subtracting interest expense from operating cash flows and also discounting at WACC.", "Choosing the highest IRR for mutually exclusive projects without checking NPV.", "Ignoring terminal working-capital recovery.", "Using accounting depreciation as a cash outflow rather than its tax effect."], "memory": "Incremental, after-tax, risk-matched, NPV-first."}}, "formulaExplorer": [{"name": "Price elasticity of demand", "topic": "Economics", "formula": "% change in quantity demanded / % change in price", "meaning": "Responsiveness of quantity demanded to price.", "variables": "Use percentage changes over the same interval; classify using the absolute value.", "example": "Price +5%, quantity −10% → elasticity magnitude 2.0.", "trap": "Do not treat the negative sign as meaning inelastic."}, {"name": "Equilibrium", "topic": "Economics", "formula": "Qd = Qs", "meaning": "Market-clearing price and quantity.", "variables": "Solve demand and supply equations simultaneously.", "example": "100−2P = 20+2P → P=20, Q=60.", "trap": "Check both equations after solving."}, {"name": "Approximate real rate", "topic": "Economics", "formula": "Real ≈ Nominal − Expected inflation", "meaning": "Approximate purchasing-power return.", "variables": "Use expected inflation for an ex ante rate.", "example": "8% nominal − 3% expected inflation = 5% real.", "trap": "Use exact Fisher when the question requests precision."}, {"name": "Exact Fisher relation", "topic": "Economics", "formula": "1 + nominal = (1 + real)(1 + expected inflation)", "meaning": "Exact compounding relationship.", "variables": "Rates must be decimals in calculations.", "example": "Real = 1.08/1.03 − 1 = 4.85%.", "trap": "Do not simply subtract when exact result is required."}, {"name": "Net present value", "topic": "Corporate Finance", "formula": "NPV = Σ CFt/(1+r)^t", "meaning": "Value added after earning the required return.", "variables": "Include CF0, incremental after-tax cash flows, and project-specific r.", "example": "PV inflows 125, cost 100 → NPV 25.", "trap": "Exclude sunk costs; include opportunity costs."}, {"name": "Profitability index", "topic": "Corporate Finance", "formula": "PI = PV future cash inflows / Initial investment", "meaning": "Present-value benefit per unit invested.", "variables": "PI > 1 corresponds to positive NPV.", "example": "PV inflows 125 / cost 100 = 1.25.", "trap": "Do not use PI instead of NPV for mutually exclusive projects without rationing."}]};